window.JLPT_META = {"title": "JLPT N2 — 直前対策", "levelsCount": 15, "levels": [{"id": 1, "file": "test01.json", "title_jp": "第1回", "title_uz": "1-bosqich", "minutes": 45, "ready": true}, {"id": 2, "file": "test02.json", "title_jp": "第2回", "title_uz": "2-bosqich", "minutes": 45, "ready": true}, {"id": 3, "file": "test03.json", "title_jp": "第3回", "title_uz": "3-bosqich", "minutes": 45, "ready": true}, {"id": 4, "file": "test04.json", "title_jp": "第4回", "title_uz": "4-bosqich", "minutes": 45, "ready": true}, {"id": 5, "file": "test05.json", "title_jp": "第5回", "title_uz": "5-bosqich", "minutes": 45, "ready": true}, {"id": 6, "file": "test06.json", "title_jp": "第6回", "title_uz": "6-bosqich", "minutes": 45, "ready": false}, {"id": 7, "file": "test07.json", "title_jp": "第7回", "title_uz": "7-bosqich", "minutes": 45, "ready": false}, {"id": 8, "file": "test08.json", "title_jp": "第8回", "title_uz": "8-bosqich", "minutes": 45, "ready": false}, {"id": 9, "file": "test09.json", "title_jp": "第9回", "title_uz": "9-bosqich", "minutes": 45, "ready": false}, {"id": 10, "file": "test10.json", "title_jp": "第10回", "title_uz": "10-bosqich", "minutes": 45, "ready": false}, {"id": 11, "file": "test11.json", "title_jp": "第11回", "title_uz": "11-bosqich", "minutes": 45, "ready": false}, {"id": 12, "file": "test12.json", "title_jp": "第12回", "title_uz": "12-bosqich", "minutes": 45, "ready": false}, {"id": 13, "file": "test13.json", "title_jp": "第13回", "title_uz": "13-bosqich", "minutes": 45, "ready": false}, {"id": 14, "file": "test14.json", "title_jp": "第14回", "title_uz": "14-bosqich", "minutes": 45, "ready": false}, {"id": 15, "file": "test15.json", "title_jp": "第15回", "title_uz": "15-bosqich", "minutes": 45, "ready": false}]};
window.JLPT_TESTS = {"1": {"id": 1, "title_jp": "第1回 模擬テスト", "title_uz": "1-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t1-v1-1", "options": ["こうぎ", "こうき", "ぎょうぎ", "ぎょうき"], "answer": 3, "tr": "U bolaligida odob-axloq qoidalarini oilada qattiq o'rgatilgan edi.", "stem": "彼女は子どものとき、【行儀作法】を家庭で厳しく教え込まれた。", "reading": "ぎょうぎ", "explanation_uz": "行儀作法 → ぎょうぎさほう (odob-axloq, yurish-turish qoidalari)"}, {"id": "t1-v1-2", "options": ["いちしゅん", "いつしゅん", "いっじゅん", "いっしゅん"], "answer": 4, "tr": "Xalqaro tanlovdagi g'alaba yosh musiqachining hayotini bir lahzada o'zgartirdi.", "stem": "国際コンクールでの優勝は、若い音楽家の人生を【一瞬】にして変えた。", "reading": "いっしゅん", "explanation_uz": "一瞬 → いっしゅん (bir lahza, bir on)"}, {"id": "t1-v1-3", "options": ["さそわれて", "おそわれて", "とらわれて", "うたわれて"], "answer": 1, "tr": "«Oz qoldi» degan so'zga qiziqib (vasvasaga tushib), beixtiyor teledo'kondan xarid qilib qo'ydim.", "stem": "「残りわずか」の声に【誘われて】、思わずテレビショッピングで買い物をしてしまった。", "reading": "さそわれて", "explanation_uz": "誘う → さそう (taklif qilmoq, qiziqtirmoq / vasvasaga solmoq)"}, {"id": "t1-v1-4", "options": ["ぶっぞう", "ぶっそう", "ぶつぞう", "ぶつそう"], "answer": 2, "tr": "Ilgari tinch shahar edi, yaqinda esa xavfli/notinch hodisalar ko'paydi.", "stem": "以前は静かな町だったのに、最近は【物騒な】事件が多くなった。", "reading": "ぶっそう", "explanation_uz": "物騒 → ぶっそう (xavfli, bexavotir bo'lmagan, notinch)"}, {"id": "t1-v1-5", "options": ["ええせい", "えいぜい", "えいせい", "ええぜい"], "answer": 3, "tr": "Grippdan o'lim darajasi pastligining bir sababi xalqning gigiyena bilimi yuqoriligidir.", "stem": "インフルエンザでの死亡率が低い理由の1つに、国民の【衛生】知識の高さがあげられる。", "reading": "えいせい", "explanation_uz": "衛生 → えいせい (gigiyena, sanitariya)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t1-v2-6", "options": ["飯きられて", "飽きられて", "館きられて", "飲きられて"], "answer": 2, "tr": "Tejamkor hayotdan charchagan iste'molchilarga faqat arzon bo'lgan mahsulotlar jonga tegib qoldi.", "stem": "節約生活に疲れた消費者に安いだけの商品は【あきられて】きた。", "reading": "あきられて", "explanation_uz": "飽きる → あきる (me'daga tegmoq, jonga tegmoq)"}, {"id": "t1-v2-7", "options": ["古展", "箇典", "個展", "古典"], "answer": 4, "tr": "«Genji monogatari» — Yaponiyaning vakillik qiluvchi mumtoz (klassik) adabiyotidir.", "stem": "『源氏物語』は日本の代表的な【こてん】文学だ。", "reading": "こてん", "explanation_uz": "古典 → こてん (mumtoz, klassik)"}, {"id": "t1-v2-8", "options": ["難いて", "嘆いて", "喝いて", "漢いて"], "answer": 2, "tr": "O'z kamchiliklaringga faqat qayg'uravermasdan (hasrat chekmasdan), kuchli tomonlaringni rivojlantirishing kerak.", "stem": "自分の欠点を【なげいて】ばかりいないで、長所を伸ばすべきだ。", "reading": "なげいて", "explanation_uz": "嘆く → なげく (qayg'urmoq, hasrat chekmoq, nola qilmoq)"}, {"id": "t1-v2-9", "options": ["激増", "激象", "劇増", "劇象"], "answer": 1, "tr": "Stress ko'p bo'lgan zamonamizda depressiyaga chalingan odamlar keskin ko'paymoqda.", "stem": "ストレスの多い現代、うつ病を病む人が【げきぞう】している。", "reading": "げきぞう", "explanation_uz": "激増 → げきぞう (keskin/tez ko'payish)"}, {"id": "t1-v2-10", "options": ["単水", "短水", "淡水", "採水"], "answer": 3, "tr": "Yuqori texnologiya tufayli dengiz suvi chuchuklashtirilib, ichish mumkin bo'ldi.", "stem": "高い技術力のおかげで海水が【たんすい】化されて、飲めるようになった。", "reading": "たんすい", "explanation_uz": "淡水 → たんすい (chuchuk suv) (淡水化 = chuchuklashtirish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t1-v3-11", "options": ["質", "化", "力", "性"], "answer": 3, "tr": "O'z qo'ling bilan harflarni yozsang, xotira qobiliyati (kuchi) yanada oshar ekan.", "stem": "自分の手で文字を書くと記憶（　）がより高まるそうだ。", "explanation_uz": "記憶力 (きおくりょく) = xotirlash qobiliyati"}, {"id": "t1-v3-12", "options": ["品", "作", "物", "者"], "answer": 2, "tr": "Bu surat uning eng mashhur (namoyondalik) asaridir.", "stem": "この絵は彼の代表（　）である。", "explanation_uz": "代表作 (だいひょうさく) = muallifning eng mashhur / vakillik asari"}, {"id": "t1-v3-13", "options": ["区", "場", "所", "域"], "answer": 1, "tr": "Bu yer baland tog' o'simliklarini muhofaza qilish hududidir (zonasidir).", "stem": "ここは高山植物の保護（　）です。", "explanation_uz": "保護区 (ほごく) = qo'riqxona zonasi, muhofaza hududi"}, {"id": "t1-v3-14", "options": ["軍", "陣", "戦", "権"], "answer": 3, "tr": "Professional beysbolning rasmiy musobaqasi (o'yini) boshlanish arafasida.", "stem": "プロ野球の公式（　）が始まるところだ。", "explanation_uz": "公式戦 (こうしきせん) = rasmiy o'yin / musobaqa"}, {"id": "t1-v3-15", "options": ["悪", "副", "複", "反"], "answer": 2, "tr": "Bu dorining oshqozonni bezovta qiladigan nojo'ya ta'siri (aks ta'siri) bor.", "stem": "この薬は胃を荒らす（　）作用がある。", "explanation_uz": "副作用 (ふくさよう) = nojo'ya ta'sir"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t1-v4-16", "options": ["滅多に", "滅多", "まれ", "たま"], "answer": 2, "tr": "«Tarix takrorlanadi» deyiladi-ku, lekin bir xil bo'lib takrorlanishi kamdan-kam bo'ladi.", "stem": "「歴史は繰り返す」と言うが、同じように繰り返されることは（　）にない。", "reading": "めった", "explanation_uz": "滅多に〜ない (めったに〜ない) = kamdan-kam, deyarli bo'lmaydi"}, {"id": "t1-v4-17", "options": ["それぞれ", "しばしば", "ぞくぞく", "とうとう"], "answer": 2, "tr": "Kir yuvish mashinasi bunchalik tez-tez buzilaversa, yangisini sotib olishdan boshqa chora yo'q.", "stem": "洗濯機がこう（　）故障するのでは、買い替えるしかない。", "explanation_uz": "しばしば = tez-tez, bot-bot (たびたび)"}, {"id": "t1-v4-18", "options": ["セキュリティー", "コンディション", "オペレーション", "コンタクト"], "answer": 1, "tr": "Bu hududda yolg'iz yashovchi qariyalar ko'p bo'lib, xavfsizlik (security) masalasida xavotir bor.", "stem": "この地域は一人暮らしのお年寄りが多く、（　）に不安がある。", "explanation_uz": "セキュリティー = xavfsizlik, xavfsizlik tizimi"}, {"id": "t1-v4-19", "options": ["信頼", "資本", "舞台", "現実"], "answer": 3, "tr": "Mening orzum — global maydonda (sahna) faoliyat yuritishdir.", "stem": "私の夢は、グローバルな（　）で活躍することです。", "explanation_uz": "舞台 (ぶたい) = sahna, maydon (global maydon = グローバルな舞台)"}, {"id": "t1-v4-20", "options": ["独特", "格別", "特例", "特殊"], "answer": 1, "tr": "Bu uyning qurilish uslubi faqat shu hududga xosdir (o'ziga xosdir).", "stem": "この家の建て方は、この地方（　）のものです。", "explanation_uz": "独特 (どくとく) = o'ziga xos, betakror"}, {"id": "t1-v4-21", "options": ["調節", "管理", "修正", "修繕"], "answer": 4, "tr": "Tomni ta'mirlash bahonasida quyosh energiyasi tizimini o'rnatishga qaror qildik.", "stem": "屋根を（　）するついでに、太陽光発電システムを取り入れることにした。", "explanation_uz": "修繕 (しゅうぜん) = ta'mirlash, tuzatish"}, {"id": "t1-v4-22", "options": ["切り抜き", "切り取り", "書き取り", "選り抜き"], "answer": 1, "tr": "Gazetadagi taom maqolalaridan qirqib olingan parchalarni taomnoma tuzishda qo'llanma qilyapman.", "stem": "新聞の料理記事の（　）を献立の参考にしている。", "explanation_uz": "切り抜き (きりぬき) = gazetadan qirqib olingan parcha (vyrezka)"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t1-v5-23", "options": ["乗り換えになる", "交差している", "一体化している", "つながっている"], "answer": 4, "tr": "Bu xususiy temiryo'l keyingi bekatda JR bilan tutashgan (bog'langan).", "stem": "この私鉄は次の駅でJRと【連絡している】。", "reading": "れんらくしている", "explanation_uz": "連絡している = つながっている (bog'langan, tutashgan)"}, {"id": "t1-v5-24", "options": ["騒がれた", "おかしかった", "当たらなかった", "難しかった"], "answer": 3, "tr": "Saylov bo'yicha taxmin xato chiqdi (to'g'ri chiqmadi).", "stem": "選挙の予想が【外れた】。", "reading": "はずれた", "explanation_uz": "外れる (はずれる) = 当たらなかった (to'g'ri chiqmadi, adashdi)"}, {"id": "t1-v5-25", "options": ["非常に", "改めて", "逆に", "多少"], "answer": 3, "tr": "Yaqin yo'ldan borgan bo'lsak-da, aksincha ko'proq vaqt ketdi.", "stem": "近道したのに【かえって】時間がかかった。", "explanation_uz": "かえって = 逆に (aksincha, teskarisiga)"}, {"id": "t1-v5-26", "options": ["率直に", "適当に", "簡単に", "自由に"], "answer": 1, "tr": "Ochiqchasiga (samimiy) fikrimni aytsam, u taklifga qarshiman.", "stem": "はっきり意見を申し上げるなら、その案には【反対です】。", "explanation_uz": "率直に (そっちょくに) = はっきりと、ありのままに (ochiqchasiga, to'g'ridan-to'g'ri)"}, {"id": "t1-v5-27", "options": ["進めた", "終わらせた", "引き受けた", "補った"], "answer": 4, "tr": "Rahbar dam olish kuni ishga chiqib, xodimining kechikkan ishini to'ldirdi (yordam berdi).", "stem": "上司が休日出勤して、部下の遅れた仕事を【カバーした】。", "explanation_uz": "カバーした = 補った (おぎなった — kam-ko'stini to'ldirdi, qopladi)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t1-v6-28", "options": ["この仕事には能力のある人物を通用する予定だ。", "そんなへたな言い訳は、私には通用しない。", "この危険な仕事に、これだけの給料では通用しない。", "この本はあなたの勉強に通用するのでお読みなさい。"], "answer": 2, "tr": "通用 (つうよう) = yaroqli bo'lmoq, o'tmoq, qabul qilinmoq.", "stem": "通用", "optsTr": ["Bu ishga qobiliyatli odamni 'o'tkazish' rejamiz bor (noto'g'ri).", "Bunday puch bahonalar menga o'tmaydi (ish bermaydi). (to'g'ri)", "Bu xavfli ishga buncha oylik 'o'tmaydi' (noto'g'ri).", "Bu kitob sizning o'qishingizga 'o'tadi', o'qing (noto'g'ri)."]}, {"id": "t1-v6-29", "options": ["論文は、あらすじ書き上がっています。", "会議で経営方針のあらすじが決まった。", "仲間同士で激しいあらすじになってしまった。", "この小説のあらすじを400字以内にまとめなさい。"], "answer": 4, "tr": "あらすじ = qisqacha mazmun (syujet bayoni).", "stem": "あらすじ", "optsTr": ["Ilmiy maqola 'qisqacha syujeti' yozib bo'lindi (noto'g'ri).", "Yig'ilishda boshqaruv rejasining 'syujeti' hal bo'ldi (noto'g'ri).", "Do'stlar o'rtasida shiddatli 'syujet' yuz berdi (noto'g'ri).", "Ushbu romanning qisqacha mazmunini (syujetini) 400 belgidan oshirmay xulosa qiling. (to'g'ri)"]}, {"id": "t1-v6-30", "options": ["だれにでも迷惑な思い出の1つや2つはあるものだ。", "込んでいる電車の中で新聞を広げるのは、他の客に迷惑だ。", "こんな少ない給料では家族の生活はいい迷惑だ。", "病気だとわかったときにはもうすでに手遅れで、迷惑な状態だった。"], "answer": 2, "tr": "迷惑 (めいわく) = boshqalarga noqulaylik/tashvish tug'dirish.", "stem": "迷惑", "optsTr": ["Har kimda ham 'noqulay' xotira bitta-ikkita bo'ladi (noto'g'ri).", "Odam gavjum poyezdda gazeta yoyish — boshqa yo'lovchilarga halal beradi (noqulaylikdir). (to'g'ri)", "Bunday kam maosh bilan oilaning turmushi 'katta noqulaylik' (noto'g'ri).", "Kasal ekani bilinganda kech bo'lib, 'noqulay' holatda edi (noto'g'ri)."]}, {"id": "t1-v6-31", "options": ["この店は土日も休まず売買している。", "この商品は売買がよくて、生産が追いつかない。", "やむを得ない事情でこの土地を売買することにした。", "不動産を売買するには資格が必要だ。"], "answer": 3, "tr": "売買 (ばいばい) = oldi-sotdi (savdo qilish).", "stem": "売買", "optsTr": ["Bu do'kon shanba-yakshanba ham dam olmasdan 'oldi-sotdi qiladi' (noto'g'ri — 営業).", "Bu mahsulotning 'oldi-sotdisi' yaxshi bo'lib, yetkazib bo'lmayapti (noto'g'ri — 売れ行き).", "Majburiy vaziyat tufayli ushbu yerni oldi-sotdi qilishga (sotishga) qaror qildik. (to'g'ri)", "Ko'chmas mulkni oldi-sotdi qilish uchun litsenziya kerak (noto'g'ri)."]}, {"id": "t1-v6-32", "options": ["新しい法案は過半数の賛成を得たので国会で成立した。", "今回の地震の被害者の数は過半数だった。", "狭い会場にファンが過半数で押しかけてきた。", "彼が犯人だという証拠は過半数である。"], "answer": 1, "tr": "過半数 (かはんすう) = ko'pchilik qism (yarmidan ko'pi, 50% dan ortig'i).", "stem": "過半数", "optsTr": ["Yangi qonun loyihasi yarmidan ko'pining (ko'pchilikning) ovozini olib, parlamentda ma'qullandi. (to'g'ri)", "Bu galgi zilzila qurbonlarining soni 'ko'pchilik' edi (noto'g'ri).", "Tor zalga muxlislar 'ko'pchilik bo'lib' bostirib keldi (noto'g'ri).", "U jinoyatchi ekanligi haqidagi dalil 'yarmidan ko'p' (noto'g'ri)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t1-g1-33", "options": ["際に", "あげく", "上で", "ついでに"], "answer": 3, "tr": "Ishni o'zgartirish yaxshilab o'ylab ko'rgach qabul qilgan qarorim bo'lgani uchun, xato bo'lsa ham mayli.", "stem": "転職はよく考えた（　）決めたことですから、たとえ失敗してもかまいません。", "explanation_uz": "〜た上で (うえで) = ...gach, ...ganidan so'ng (oldin sinchiklab o'ylab, keyin qilingan harakat)"}, {"id": "t1-g1-34", "options": ["からいって", "だからといって", "だけあって", "といって"], "answer": 1, "tr": "Soliqlar oshishi qiyin. Ammo qariyalar soni tobora oshib borayotgan voqelikdan kelib chiqsak, iloj yo'q.", "stem": "税金が上がるのは困る。しかし高齢者がますます増える現実（　）、仕方がない。", "explanation_uz": "〜からいって = ...dan kelib chiqib mulohaza yuritilsa"}, {"id": "t1-g1-35", "options": ["的に", "用に", "寄りに", "向けに"], "answer": 4, "tr": "Bu yerdagi tay taomlari yaponlar uchun (yaponlarga mo'ljallab) achchiqligi biroz pasaytirilgan.", "stem": "ここのタイ料理は、日本人（　）すこし辛さをおさえてあります。", "explanation_uz": "〜向けに (むけに) = ...uchun maxsus mo'ljallangan"}, {"id": "t1-g1-36", "options": ["ことでは", "ものでは", "かぎりでは", "まででは"], "answer": 3, "tr": "Mening ko'rganim bo'yicha (kuzatishim doirasida) qaralsa, Yamada-sanni bunchalik yomon odam deb hisoblay olmayman.", "stem": "私が見た（　）、山田さんがそんなに悪い人だとは思えない。", "explanation_uz": "〜かぎりでは = ...ganimcha, ...doirasida hukm qilinsa"}, {"id": "t1-g1-37", "options": ["わけ", "もの", "こと", "はず"], "answer": 3, "tr": "«O'zim bo'lsam bundan ham yaxshi qilardim» deydigan bo'lsang, o'zing qilib ko'rishing kerak-da.", "stem": "「自分ならもっとうまくやれる」と言うなら、君がやってみる（　）だね。", "explanation_uz": "〜ことだ = ...qilish kerak (maslahat yoki kinoya)"}, {"id": "t1-g1-38", "options": ["反対で", "以外で", "片面で", "一方で"], "answer": 4, "tr": "Turmush qurgandan keyin ham ishlaydigan ayollar ko'payayotgan bir paytda, uy bekasi bo'lishni xohlaydigan ayollar ham ko'paymoqda.", "stem": "結婚後も仕事をする女性が増える（　）、専業主婦になりたい女性も増えている。", "explanation_uz": "〜一方で (いっぽうで) = bir tomondan ... bo'lsa, ikkinchi tomondan esa..."}, {"id": "t1-g1-39", "options": ["のあまり", "のせいか", "のくせに", "のおかげで"], "answer": 1, "tr": "Tekshiruv natijasidan haddan tashqari xavotirlanganimdan, tonggacha uxlay olmadim.", "stem": "検査の結果が心配（　）、朝まで眠ることができなかった。", "explanation_uz": "〜あまり = ...ning haddan ziyodligi natijasida"}, {"id": "t1-g1-40", "options": ["ことから", "ことだから", "ことに", "ことなら"], "answer": 1, "tr": "Bu meva salomatlik uchun juda foydali bo'lgani sababli, qadimdan «shifokorga hojat qoldirmas» deb ham ataladi.", "stem": "この果物はとても健康にいい（　）、昔から「医者いらず」とも呼ばれる。", "explanation_uz": "〜ことから = ...bo'lganligi sababli (sabab/kelib chiqish)"}, {"id": "t1-g1-41", "options": ["知りつつも", "知らないものの", "知るからには", "知らないくせに"], "answer": 1, "tr": "Salomatlikka zarar ekanligini bilsa ham, nega tamakini tashlay olmaydi-a!", "stem": "健康に悪いと（　）、どうして煙草がやめられない。", "explanation_uz": "〜つつも = ...sa ham, qaramay (ziddiyatli harakat)"}, {"id": "t1-g1-42", "options": ["するわけにはいかない", "しないわけにはいかない", "するべきでない", "してはいられない"], "answer": 2, "tr": "Agar oramizda hech kimning haydovchilik guvohnomasi bo'lmasa, men haydamasam bo'lmaydi (haydashga majburman).", "stem": "このなかでだれも免許を持っていないなら、私が運転（　）ね。", "explanation_uz": "〜ないわけにはいかない = ...maslikning iloji yo'q, shart"}, {"id": "t1-g1-43", "options": ["気に入らなかったにしても", "気に入らなかったとしたら", "気に入ったとしても", "気に入ったとしたら"], "answer": 1, "tr": "Garchi sovg'a yoqmagan bo'lsa ham, uni bergan kishiga hech bo'lmaganda minnatdorchilik maktubi yozish odobdandir.", "stem": "たとえ贈り物が（　）、下さった方にお礼の手紙くらい書くものですよ。", "explanation_uz": "たとえ〜にしても = garchi ... bo'lgan taqdirda ham"}, {"id": "t1-g1-44", "options": ["伝えていただけますか", "お伝えいただけますか", "お伝えになれますか", "お伝えいたしましょうか"], "answer": 2, "tr": "A: «Afsuski Tanaka tashqariga chiqqan edilar.»\nB: «U holda, A kompaniyasining Yamadasidan qo'ng'iroq bo'lganini yetkazib qo'ya olasizmi?»", "stem": "A「あいにく田中は外出しております。」\nB「では、A社の山田から電話があったと（　）。」", "explanation_uz": "お伝えいただけますか = yetkazib bera olasizmi (xushmuomala so'rov: お〜いただく)"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t1-g2-45", "options": ["やれる", "やって", "できるか", "ものなら"], "answer": 4, "tr": "To'g'ri tartib: そんな勉強のやり方で合格できるか、やれるものならやってみればいいよ。", "explanation_uz": "To'g'ri tartib: 合格[できるか]、[やれる][★ものなら][やって]みればいいよ。 (3 → 1 → 4 → 2)", "prefix": "そんな勉強のやり方で合格", "suffix": "みればいいよ。", "starPos": 3, "order": [3, 1, 4, 2]}, {"id": "t1-g2-46", "options": ["がち", "飲める", "忘れ", "ありがたさを"], "answer": 3, "tr": "To'g'ri tartib: 日本人は、どこでも水がただで飲めるありがたさを忘れがちです。", "explanation_uz": "To'g'ri tartib: ただで[飲める][ありがたさを][★忘れ][がち]です。 (2 → 4 → 3 → 1)", "prefix": "日本人は、どこでも水がただで", "suffix": "です。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t1-g2-47", "options": ["なれば", "という", "ものでは", "平気になる"], "answer": 2, "tr": "To'g'ri tartib: 歯医者に行くのは、大人になれば平気になるというものではありません。", "explanation_uz": "To'g'ri tartib: 大人になれば[平気になる][という][★ものでは]ありません。 (1 → 4 → 2 → 3)", "prefix": "歯医者に行くのは、大人に", "suffix": "ありません。", "starPos": 3, "order": [1, 4, 2, 3]}, {"id": "t1-g2-48", "options": ["忘れた", "に", "かけるのを", "ばかり"], "answer": 1, "tr": "To'g'ri tartib: 私が家のかぎをかけるのを忘れたばかりに、どろぼうに入られてしまった。", "explanation_uz": "To'g'ri tartib: かぎを[かけるのを][★忘れた][ばかり][に] (3 → 1 → 4 → 2)", "prefix": "私が家のかぎを", "suffix": "どろぼうに入られてしまった。", "starPos": 2, "order": [3, 1, 4, 2]}, {"id": "t1-g2-49", "options": ["ある", "以上は", "うつす", "おそれが"], "answer": 4, "tr": "To'g'ri tartib: B「病気を人にうつすおそれがある以上は、学校を休んだほうがいいわよ。」", "explanation_uz": "To'g'ri tartib: 病気を人に[うつす][★おそれが][ある][以上は] (3 → 4 → 1 → 2)", "prefix": "B「病気を人に", "suffix": "学校を休んだほうがいいわよ。」", "starPos": 2, "order": [3, 4, 1, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "囲碁の広がり", "passage": "少し前の日本の家庭には、たいてい囲碁（いご）の道具があった {{50}} 。子どもたちは、祖父や近所のおじさんたちが遊ぶのをそばで見て、自分たちもルールを覚えていった。だが最近は核家族が増えて、ルールを知らない若い親は子どもに教えることがなくなり、子どもたちも囲碁からは離れていった。\n囲碁は本当に強くなるためには、子どものときから始めるのが重要だそうだ。しかし、かつて1200万人とも言われた競技人口が300万人台にまで落ち込み、しかも子どもの数がとても少なくなった。囲碁にかかわる人々は、日本の囲碁の将来に {{51}} 。\nそこへ救いの神が現れた。1998年から雑誌に囲碁がテーマのマンガが連載され、大ヒットしたのだ。マンガはテレビアニメにもなり、子ども向けに囲碁を教えるテレビ番組も放送された。このマンガを {{52}} として、囲碁を始めた子どもはざっと100万人と言われる。\nだが何しろ日本人は熱しやすく冷めやすい国民だ。事実、すでに新しく囲碁を始める人は {{53}} 。\n「この機会を一時のブームで {{54}} 」と、関係者はいろいろなアイデアを出している。", "passage_tr": "Biroz avvalgi yapon xonadonlarida odatda go (igo) o'yini anjomlari bo'lar edi. Bolalar bobolari va qo'shni amakilarning o'ynashini yonidan kuzatib, o'zlari ham qoidalarini o'rganib olishardi. Ammo so'nggi paytlarda alohida yashovchi oilalar ko'payib, qoidani bilmaydigan yosh ota-onalar bolalariga o'rgatmay qo'ydi, bolalar ham godan uzoqlashdi.\nGo o'yinida chinakam kuchli bo'lish uchun bolalikdan boshlash muhim ekan. Biroq, bir paytlar 12 million kishi deb aytilgan o'yinchilar soni 3 milliongacha tushib ketdi, buning ustiga bolalar soni ham juda kamaydi. Go sohasidagi insonlar yapon gosi kelajagidan qattiq xavotirda edilar.\nShu paytda najotkor paydo bo'ldi. 1998-yildan jurnalda go mavzusidagi manga chop etila boshlab, juda mashhur bo'ldi. Manga teleanimatsiyaga aylandi, bolalar uchun go o'rgatadigan teledasturlar ham efirga uzatildi. Ushbu mangani turtki (sabab) qilib, go o'ynashni boshlagan bolalar taxminan 1 million kishi deb aytiladi.\nLekin nima bo'lganda ham yaponlar tez qizib, tez soviydigan xalqdir. Aslida allaqachon yangidan goni boshlayotganlar kamayib bormoqda.\n«Ushbu imkoniyatni vaqtinchalik shov-shuv bilan tugatib qo'ymaylik» deb, soha xodimlari turli g'oyalarni ilgari surmoqdalar.", "questions": [{"id": "t1-g3-50", "options": ["ことだ", "ものだ", "ところだ", "ようだ"], "answer": 2, "tr": "かつての習慣: 囲碁の道具があった[ものだ] (Ilgari bo'lar edi - o'tmishdagi xotira/odat).", "explanation_uz": "〜ものだ = o'tmishdagi doimiy holat / xotira", "blankNo": "50"}, {"id": "t1-g3-51", "options": ["大きな希望を持っていた", "強い不安を持っていた", "安心しかねなかった", "少しの心配もなかった"], "answer": 2, "tr": "日本の囲碁の将来に[強い不安を持っていた] (Kelajagidan qattiq xavotirda edilar).", "explanation_uz": "O'yinchilar soni keskin kamaygani sababli: 強い不安を持っていた", "blankNo": "51"}, {"id": "t1-g3-52", "options": ["きっかけ", "もと", "事情", "原因"], "answer": 1, "tr": "このマンガを[きっかけ]として = Ushbu mangani turtki qilib / bahona qilib.", "explanation_uz": "〜をきっかけとして = ...ni turtki / sabab qilib olib", "blankNo": "52"}, {"id": "t1-g3-53", "options": ["減りつつある", "減りそうもない", "増えるかもしれない", "増えざるを得ない"], "answer": 1, "tr": "新しく囲碁を始める人は[減りつつある] = Yangi boshlovchilar kamayib bormoqda.", "explanation_uz": "〜つつある = tobora ...yotgan bo'lmoq (davomiy o'zgarish)", "blankNo": "53"}, {"id": "t1-g3-54", "options": ["終わらせたい", "終わらせよう", "終わらせまい", "終わりたくない"], "answer": 3, "tr": "この機会を一時のブームで[終わらせまい]と = bir lahzalik shov-shuv bilan tugatib qo'ymaylik deb.", "explanation_uz": "〜まい = ...maslik niyati / qarori (tugatmaslikka qaror qilish)", "blankNo": "54"}]}]}]}, "2": {"id": 2, "title_jp": "第2回 模擬テスト", "title_uz": "2-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t2-v1-1", "options": ["はめられる", "おさめられる", "とられる", "しばられる"], "answer": 4, "tr": "Internet muhiti yaxshilansa, ofisga bog'lanib qolmasdan (cheklanmasdan), qayerda bo'lsa ham ishlash mumkin.", "stem": "ネット環境が整えばオフィスに【縛られる】ことなく、どこにいても仕事ができる。", "reading": "しばられる", "explanation_uz": "縛る → しばる (bog'lamoq, cheklamoq)"}, {"id": "t2-v1-2", "options": ["そうぞう", "ずうずう", "あらあら", "いまいま"], "answer": 1, "tr": "Poyezd ichida ko'plab bolalar ketayotgani sababli juda shovqin-suronli edi.", "stem": "電車の中は、たくさんの子どもが乗っていて【騒々しかった】。", "reading": "そうぞうしかった", "explanation_uz": "騒々しい → そうぞうしい (shovqinli, g'ovur-g'uvur)"}, {"id": "t2-v1-3", "options": ["ちょうし", "ちょうじ", "しゅうじ", "じゅうし"], "answer": 4, "tr": "Bizning kompaniya bu yildan suhbat sonini ko'paytirib, bilimdan ko'ra shaxsiyatga ahamiyat berib (muhim deb bilib) xodimlarni qabul qiladi.", "stem": "我が社は今年から面接の回数を増やして、知識より人物【重視】で社員を採用する。", "reading": "じゅうし", "explanation_uz": "重視 → じゅうし (muhim deb bilish, ahamiyat qaratish)"}, {"id": "t2-v1-4", "options": ["こうかん", "ごうがん", "こうがん", "ごうかん"], "answer": 1, "tr": "Xaridlar orqali to'plangan ballarni tovar kuponlariga almashtirish mumkin.", "stem": "お買い物でためたポイントは、商品券に【交換】できます。", "reading": "こうかん", "explanation_uz": "交換 → こうかん (almashtirish, o'zaro almashuv)"}, {"id": "t2-v1-5", "options": ["ほうぞう", "ほうそう", "ほうそう", "ほうぞう"], "answer": 3, "tr": "Supermarketlarda oziq-ovqatlarni qadoqlashni (o'rab-chirmashni) kamaytirish bo'yicha harakatlar olib borilmoqda.", "stem": "スーパーでは食品の【包装】を少なくする活動が進んでいる。", "reading": "ほうそう", "explanation_uz": "包装 → ほうそう (qadoqlash, o'rash)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t2-v2-6", "options": ["暖房", "暖冒", "断房", "断冒"], "answer": 1, "tr": "Quyosh energiyasi hosil qiladigan issiqlik isitish tizimiga, yorug'lik esa elektrga ishlatilishi mumkin.", "stem": "太陽エネルギーが生み出す熱は【だんぼう】に、光は電気に利用できる。", "reading": "だんぼう", "explanation_uz": "暖房 → だんぼう (isitish tizimi)"}, {"id": "t2-v2-7", "options": ["勘違い", "肝違い", "感違い", "塞違い"], "answer": 1, "tr": "U ikki kishini er-xotin deb yanglish (noto'g'ri tushunadigan) o'ylaydigan odamlar ko'p.", "stem": "あの2人は夫婦だと【かんちがい】している人が多い。", "reading": "かんちがい", "explanation_uz": "勘違い → かんちがい (yanglishish, noto'g'ri tushunish)"}, {"id": "t2-v2-8", "options": ["焦らして", "燃らして", "照らして", "烈らして"], "answer": 3, "tr": "Umumiy qoidalar (aql-idrok) bilan qiyoslab (solishtirib) ko'rsang, hozir nima qilishing kerakligi ayon bo'ladi.", "stem": "常識に【てらして】考えてみれば、君が今、何をすべきかわかるだろう。", "reading": "てらして", "explanation_uz": "照らす → てらす (solishtirmoq, qiyoslamoq; yoritmoq)"}, {"id": "t2-v2-9", "options": ["地敷", "地版", "地番", "地盤"], "answer": 4, "tr": "Bu atrofda zilzila oqibatida yer poydevori (tuproq qatlami) cho'kib ketdi.", "stem": "このあたりは地震で【じばん】が沈んでしまった。", "reading": "じばん", "explanation_uz": "地盤 → じばん (yer sathi, poydevor tuproq)"}, {"id": "t2-v2-10", "options": ["汚洗", "御染", "汚染", "冒染"], "answer": 3, "tr": "Zavod halokati tufayli zararli moddalar oqib, daryo ifloslandi.", "stem": "工場の事故で有害物質が流れ、川が【おせん】された。", "reading": "おせん", "explanation_uz": "汚染 → おせん (ifloslanish, zaharlanish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t2-v3-11", "options": ["無", "反", "非", "不"], "answer": 3, "tr": "Hindistonlik Gandi zo'ravonliksiz (tinchlik) tamoyiliga tayanib, mustaqillik harakatiga boshchilik qildi.", "stem": "インドのガンジーは（　）暴力を信条に独立運動を指導した。", "explanation_uz": "非暴力 (ひぼうりょく) = zo'ravonliksizlik tamoyili"}, {"id": "t2-v3-12", "options": ["人", "風", "流", "派"], "answer": 4, "tr": "Yamada janoblari o'ziga xos uslubdagi (individual tipdagi) aktyor sifatida faoliyat yuritmoqda.", "stem": "山田氏は、個性（　）俳優として活躍している。", "explanation_uz": "個性派 (こせいは) = o'ziga xos individual yo'nalishga ega bo'lgan shaxs/aktyor"}, {"id": "t2-v3-13", "options": ["点", "見", "場", "所"], "answer": 1, "tr": "Barcha xodimlardan teatrni yaxshilash nuqtalari (takliflari) so'raladi.", "stem": "全社員に劇場の改善（　）を開く。", "explanation_uz": "改善点 (かいぜんてん) = yaxshilanishi kerak bo'lgan jihatlar/nuqtalar"}, {"id": "t2-v3-14", "options": ["方", "側", "界", "世"], "answer": 3, "tr": "Tabiat olami qonuniyatlariga qarshi chiqib bo'lmaydi.", "stem": "自然（　）の法則には逆らえない。", "explanation_uz": "自然界 (しぜんかい) = tabiat olami / tabiat dunyosi"}, {"id": "t2-v3-15", "options": ["近", "同", "何", "当"], "answer": 2, "tr": "Bolalar tengdosh bo'lganlari sababli, darrov do'stlashib ketishdi.", "stem": "子どもたちは（　）年齢とあって、すぐに仲よくなった。", "explanation_uz": "同年齢 (どうねんれい) = tengdosh, bir yoshdagi"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t2-v4-16", "options": ["制作", "工事", "閉鎖", "更新"], "answer": 4, "tr": "To'garakning veb-saytiga «Tadbirlar ma'lumoti»ni qo'shib, yangiladik (update qildik).", "stem": "サークルのホームページに「イベント情報」を追加し、（　）した。", "explanation_uz": "更新 (こうしん) = yangilash, yangi ma'lumot kiritish"}, {"id": "t2-v4-17", "options": ["上等", "優秀", "有効", "優良"], "answer": 2, "tr": "Eng a'lo natija ko'rsatgan talabaga universitet tomonidan rektor mukofoti beriladi.", "stem": "最も（　）な成績の学生には、大学から学長賞が贈られます。", "explanation_uz": "優秀 (ゆうしゅう) = a'lo, yetakchi, iqtidorli"}, {"id": "t2-v4-18", "options": ["重視", "指導", "活用", "刺激"], "answer": 4, "tr": "Xarid qilish kabi kundalik odat iste'molni rag'batlantirib (kuchaytirib), jamiyatni jonlantiradi.", "stem": "買い物という日常的な行いが、消費を（　）して世の中を元気にする。", "explanation_uz": "刺激 (しげき) = rag'batlantirish, qo'zg'atish"}, {"id": "t2-v4-19", "options": ["いらいら", "ぶつぶつ", "のろのろ", "まごまご"], "answer": 1, "tr": "Avtobus aslo kelavermagach, kutayotgan odamlar asta-sekin asabiylasha (g'azablana) boshladi.", "stem": "バスがなかなか来なくて、待っている人たちは次第に（　）し始めた。", "explanation_uz": "いらいら = asabiylashish, betoqat bo'lish"}, {"id": "t2-v4-20", "options": ["アプローチ", "アレンジ", "アシスト", "アドバイス"], "answer": 2, "tr": "Yapon sushisini moslashtirgan (modifikatsiya qilgan) g'arbona sushi chet elda mashhur.", "stem": "日本の寿司を（　）した洋風の寿司が海外で人気だ。", "explanation_uz": "アレンジ (arrange) = yangicha talqin qilish, moslashtirish"}, {"id": "t2-v4-21", "options": ["長期", "不変", "永遠", "不滅"], "answer": 3, "tr": "Baxt abadiy davom etishi mumkin emasmi-a?", "stem": "幸福が（　）に続くことはありえないのだろうか。", "explanation_uz": "永遠に (えいえんに) = abadiy, mangu"}, {"id": "t2-v4-22", "options": ["謙遜", "遠慮", "配慮", "恐縮"], "answer": 1, "tr": "U ulkan korporatsiya prezidenti o'zida aytarli iste'dod yo'qligini kamtarlik bilan aytadi.", "stem": "あの大企業の社長は自分にはこれといった才能はないと（　）している。", "explanation_uz": "謙遜 (けんそん) = kamtarlik qilish"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t2-v5-23", "options": ["記録した", "発表した", "重視した", "経験した"], "answer": 4, "tr": "O'yinda yutqazish alamini totib ko'rdim (boshdan kechirdim).", "stem": "試合に負けた悔しさを【味わった】。", "reading": "あじわった", "explanation_uz": "味わう → 経験した (boshdan kechirish, his qilish)"}, {"id": "t2-v5-24", "options": ["約束通り", "思いがけなく", "確かに", "都合よく"], "answer": 2, "tr": "Sayohat paytida kutilmaganda (tasodifan) eski do'stimni uchratib qoldim.", "stem": "旅先で【偶然】昔の友人に出会った。", "reading": "ぐうぜん", "explanation_uz": "偶然 → 思いがけなく (kutilmaganda, tasodifan)"}, {"id": "t2-v5-25", "options": ["変化がない", "よく変わる", "手間がかかる", "休みがない"], "answer": 1, "tr": "Zavoddagi bir xil (zerikarli, monoton) ishdan zerikib qoldim.", "stem": "工場の【単調な】作業にあきてきた。", "reading": "たんちょうな", "explanation_uz": "単調な → 変化がない (o'zgarishsiz, monoton)"}, {"id": "t2-v5-26", "options": ["のんびりした", "予想しない", "頼りになる", "元気のよい"], "answer": 3, "tr": "Yutqazib qiynalib turganda, kuchli (suyanadigan, ishonchli) ittifoqchi paydo bo'ldi.", "stem": "負けて困っているところに、【強力な】味方が現れた。", "reading": "きょうりょくな", "explanation_uz": "強力な → 頼りになる (ishonchli, suyansa bo'ladigan)"}, {"id": "t2-v5-27", "options": ["国際性がある", "物知りだ", "二カ国語を話す", "二重国籍だ"], "answer": 3, "tr": "U ikki tilda gaplashuvchi (bilingual) shaxsdir.", "stem": "彼は【バイリンガル】だ。", "explanation_uz": "バイリンガル = 二カ国語を話す (ikki tilda so'zlasha oladigan)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t2-v6-28", "options": ["彼は酒を飲むとすぐに本性を反映する。", "隠していた事実がついに世間に反映されてしまった。", "客の希望を反映して、配達のサービスを始めた。", "黒のドレスは色白の女性の美しさを特に反映していた。"], "answer": 3, "tr": "反映 (はんえい) = aks ettirish, inobatga olish.", "stem": "反映", "optsTr": ["U ichgach o'z xarakterini 'aks ettiradi' (noto'g'ri — 現す).", "Yashiringan haqiqat omma orasida 'aks etdi' (noto'g'ri — 知れ渡った).", "Mijozlarning istaklarini inobatga olib (aks ettirib), yetkazib berish xizmatini yo'lga qo'ydik. (to'g'ri)", "Qora ko'ylak oqtanli ayol go'zalligini 'aks ettirdi' (noto'g'ri — 引き立てる)."]}, {"id": "t2-v6-29", "options": ["話がおもしろくてためいきが出た。", "苦手な上司の声を聞いただけで、ぞっとためいきが出る。", "息子のひどい成績に母は思わずためいきをついた。", "プールに入る前に、ためいきをしてください。"], "answer": 3, "tr": "ためいき (溜め息) = chuqur xo'rsinish, nafas chiqarish.", "stem": "ためいき", "optsTr": ["Gap qiziq bo'lgani uchun 'xo'rsindim' (noto'g'ri — 笑った).", "Yoqtirmaydigan boshliq ovozidan qo'rqib 'xo'rsindi' (noto'g'ri).", "O'g'lining yomon baholarini ko'rib ona beixtiyor chuqur xo'rsinib qo'ydi. (to'g'ri)", "Basseynga tushishdan oldin 'xo'rsinib oling' (noto'g'ri — 準備運動)."]}, {"id": "t2-v6-30", "options": ["動物には、人間にない特殊な能力を持つものが多い。", "夜中に特殊な物音がして目が覚めた。", "彼って特殊にもてるけど、どこがいいのかしらね。", "今日は特殊にあなただけにプレゼントをあげます。"], "answer": 1, "tr": "特殊 (とくしゅ) = o'ziga xos, maxsus, g'ayrioddiy.", "stem": "特殊", "optsTr": ["Hayvonlar orasida insonda bo'lmagan o'ziga xos (maxsus) qobiliyatga ega bo'lganlari ko'p. (to'g'ri)", "Tunda 'maxsus' tovush eshitilib uyg'ondim (noto'g'ri — 奇妙な).", "U 'maxsus' mashhur (noto'g'ri — やたら).", "Bugun 'maxsus' sovg'a beraman (noto'g'ri — 特別)."]}, {"id": "t2-v6-31", "options": ["授業は個々の生徒の能力に合った加速度で進める。", "もう少し加速度をつけないと時間に遅れてしまう。", "あの人とはなぜか話の加速度が合わない。", "地上を離れた飛行機は一気に加速度を増した。"], "answer": 4, "tr": "加速度 (かそくど) = tezlanish (akseleratsiya).", "stem": "加速度", "optsTr": ["Darsni har bir o'quvchi qobiliyatiga mos 'tezlanish' bilan o'tamiz (noto'g'ri — ペース/速度).", "Biroz 'tezlanish' qo'shmasak kech qolamiz (noto'g'ri — スピード).", "U bilan gapning 'tezlanishi' to'g'ri kelmaydi (noto'g'ri — テンポ).", "Yerdan ko'tarilgan samolyot birdaniga tezlanishini oshirdi. (to'g'ri)"]}, {"id": "t2-v6-32", "options": ["私は工場建設に賛成の彼とは矛盾する立場にある。", "2人は最初から最後まで矛盾ばかりだ。", "税金は安くして行政サービスはよくしろだなんて、矛盾している。", "やっぱり聞くことと見るのでは矛盾している。"], "answer": 3, "tr": "矛盾 (むじゅん) = qarama-qarshilik, zidlik (mantiqsizlik).", "stem": "矛盾", "optsTr": ["Men zavod qurilishini qo'llagan u kishi bilan 'zid' pozitsiyadaman (noto'g'ri — 対立).", "Ikkovi boshidan oxirigacha 'zid' (noto'g'ri — 口喧嘩).", "Soliqni arzon qilib, davlat xizmatlarini yaxshilang deyish — mantiqan qarama-qarshidir (ziddir). (to'g'ri)", "Eshitish bilan ko'rish 'zid' (noto'g'ri — 異なる)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t2-g1-33", "options": ["わけ", "こと", "もの", "どころ"], "answer": 1, "tr": "Puli yo'q degani emas-ku, ammo keraksiz narsani sotib olmaslikka qaror qilganman.", "stem": "お金がない（　）ではないが、必要ないものは買わないことにしている。", "explanation_uz": "〜わけではない = mutlaqo ... degani emas (qisman rad etish)"}, {"id": "t2-g1-34", "options": ["としたら", "としても", "とすると", "となれば"], "answer": 2, "tr": "Hozirdan juda shoshib borgan taqdirda ham, baribir darsga ulgura olmasak kerak.", "stem": "これから大急ぎで行った（　）、授業に間に合わないだろう。", "explanation_uz": "〜としても = garchi ... bo'lgan taqdirda ham"}, {"id": "t2-g1-35", "options": ["最中に", "直後に", "途端に", "瞬間に"], "answer": 1, "tr": "Do'stim bilan gurunglashib turgan ayni paytimda boshqa bir do'stimdan qo'ng'iroq bo'lib qoldi.", "stem": "友人とおしゃべりをしている（　）、別の友人から電話がかかってきた。", "explanation_uz": "〜最中に (さいちゅうに) = ayni ... qilib turgan fursatda"}, {"id": "t2-g1-36", "options": ["信じかねない", "信じるしかない", "信じがたい", "信じざるを得ない"], "answer": 3, "tr": "Bu kichkina surat 100 million iyen turadi deb ishonish juda qiyin-a!", "stem": "この小さな絵が1億円もするなんて、（　）ですね。", "explanation_uz": "〜がたい = qilish/tasavvur qilish juda mushkul, qiyin"}, {"id": "t2-g1-37", "options": ["に対して", "に応じて", "に当たって", "に反して"], "answer": 4, "tr": "Bunday qiyin kitob sotilmaydi degan taxminga zid ravishda, 100 ming nusxadan ziyod sotildi.", "stem": "こんな難しい本は売れないだろうという予想（　）、10万冊以上売れた。", "explanation_uz": "〜に反して (にはんして) = ...ga qarama-qarshi o'laroq, zid bo'lib"}, {"id": "t2-g1-38", "options": ["するものか", "するものか", "しないものだ", "しないものか"], "answer": 2, "tr": "Boshqa aslo xato qilmayman deb qat'iy o'ylagan edim, ammo yana qilib qo'ydim.", "stem": "もう二度と失敗は（　）と思ったのに、またやってしまった。", "explanation_uz": "〜ものか = aslo ...mayman (qat'iy inkor qarori)"}, {"id": "t2-g1-39", "options": ["もう", "こう", "そう", "どう"], "answer": 3, "tr": "A: «Ko'rishmaganimizga ancha bo'ldi-ya!»\nB: «Haqiqatan ham. Shu mavzu esga tushgan ekan, otangizning betobligi shundan so'ng qanday bo'ldi?»", "stem": "A「お久しぶりです。」\nB「本当に。（　）言えば、お父さまの病気はその後、いかがですか。」", "explanation_uz": "そう言えば = aytgancha, shu esimga tushdi"}, {"id": "t2-g1-40", "options": ["したい", "した", "しよう", "しない"], "answer": 3, "tr": "Men turmush quramanmi yoki qurmaymanmi — bu sizga aloqasi bo'lmagan ishdir.", "stem": "私が結婚（　）がしまいが、あなたには関係ないことだ。", "explanation_uz": "〜ようが〜まいが = qilsam ham, qilmasam ham (baribir)"}, {"id": "t2-g1-41", "options": ["飲みすぎない", "飲みかねない", "飲みやすい", "飲みにくい"], "answer": 4, "tr": "Bu dorining donasi juda katta bo'lgani uchun, yutish juda noqulay (qiyin).", "stem": "この薬の粒は大きすぎて、とても（　）。", "explanation_uz": "〜にくい = qilish/yutish qiyin, noqulay"}, {"id": "t2-g1-42", "options": ["指導するしかないよ", "指導するわけがないよ", "指導するどころではないよ", "指導するはずがないよ"], "answer": 1, "tr": "A: «Chekkan bilan hamma ham kasal bo'lavermaydi-ku.»\nB: «Shunday bo'lsa-da shifokor nazdida, chekishni tashlashni tavsiya qilishdan boshqa chora yo'q.»", "stem": "A「たばこを吸っても、必ず病気になるわけではないだろう。」\nB「それでも医者にすれば、禁煙を（　）。」", "explanation_uz": "〜しかない = ...dan boshqa iloj/chora yo'q"}, {"id": "t2-g1-43", "options": ["歩くようにしたものの", "歩くようにしたところ", "歩くようにしたものが", "歩くようにしたところで"], "answer": 2, "tr": "Kompaniyadan bir bekat oldin tushib piyoda yurishga odatlangan edim, 3 oyda vaznim ancha kamaydi.", "stem": "会社の一駅前で降りて（　）、3カ月で体重がかなり減った。", "explanation_uz": "〜たところ = ...qilgan edimki, natijada..."}, {"id": "t2-g1-44", "options": ["お見せいただけますか", "見られていただけますか", "見ていただけますか", "見せていただけますか"], "answer": 4, "tr": "Yig'ilishda qatnasha olmaganim sababli, materiallarni ko'rsatib bera olasizmi?", "stem": "会議に出席できなかったので、資料を（　）", "explanation_uz": "見せていただけますか = ko'rsatib bera olasizmi (xushmuomala so'rov: 〜ていただく)"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t2-g2-45", "options": ["忘れてしまう", "忘れない", "ので", "そばから"], "answer": 3, "tr": "To'g'ri tartib: 難しい漢字は、習うそばから忘れてしまうので、忘れないうちにきちんと復習しよう。", "explanation_uz": "To'g'ri tartib: 習う[そばから][忘れてしまう][★ので][忘れない] (4 → 1 → 3 → 2)", "prefix": "難しい漢字は、習う", "suffix": "うちにきちんと復習しよう。", "starPos": 3, "order": [4, 1, 3, 2]}, {"id": "t2-g2-46", "options": ["でも", "では", "次第", "話し方"], "answer": 4, "tr": "To'g'ri tartib: 同じ言葉でも、話し方次第では印象が変わってしまうことがある。", "explanation_uz": "To'g'ri tartib: 同じ言葉[でも][★話し方][次第][では] (1 → 4 → 3 → 2)", "prefix": "同じ言葉", "suffix": "印象が変わってしまうことがある。", "starPos": 2, "order": [1, 4, 3, 2]}, {"id": "t2-g2-47", "options": ["最初の", "限って", "無料", "レッスンに"], "answer": 2, "tr": "To'g'ri tartib: この学校では、最初のレッスンに限って無料で受けることができます。", "explanation_uz": "To'g'ri tartib: [最初の][レッスンに][★限って][無料] (1 → 4 → 2 → 3)", "prefix": "この学校では、", "suffix": "で受けることができます。", "starPos": 3, "order": [1, 4, 2, 3]}, {"id": "t2-g2-48", "options": ["の", "わりには", "年齢", "ピアノ"], "answer": 1, "tr": "To'g'ri tartib: この子は年齢のわりにはピアノが上手だ。", "explanation_uz": "To'g'ri tartib: この子は[年齢][★の][わりには][ピアノ] (3 → 1 → 2 → 4)", "prefix": "この子は", "suffix": "が上手だ。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t2-g2-49", "options": ["取る", "成績から", "こんな成績を", "見ても"], "answer": 3, "tr": "To'g'ri tartib: あの学生の今までの成績から見ても、こんな成績を取るなんて信じられない。", "explanation_uz": "To'g'ri tartib: [成績から][見ても][★こんな成績を][取る] (2 → 4 → 3 → 1)", "prefix": "あの学生の今までの", "suffix": "なんて信じられない。", "starPos": 3, "order": [2, 4, 3, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "寿司の歴史と工夫", "passage": "あなたは日本のすし屋のカウンターで、「お好み」ですしを食べたことがありますか。\nカウンターのケースの中を見ながら、好きな魚を選び、それを注文して、にぎってもらうので、いちばんおいしい状態で食べられます。ただ自分がどれくらい食べたか、金額が {{50}} 注意が必要です。\nこのとき、たとえば「マグロ」と注文すると、通常、マグロのすしが2つ出てきます。なぜそうなのか。江戸時代のおすしは大きかったので、2つに切って出したなごりとか、計算しやすくするためだとか、いろいろな説があります。結局、はっきりとはわからなくて、「昔からそうなっている」としか {{51}} 。\nところで、この場合、 {{52}} で行けば食べればいいけれど、1人で行って10個食べるとしたら、魚は5種類しか食べられません。ある回転ずし店で、1枚の皿に違う種類のすしを1つずつ2個、乗せ始めました。これなら、食べた寿司の数だけ {{53}} が食べられるので人気が出て、客が増えたそうです。考えたら単純なアイデアです。でも「昔からそうなっている」ことをちょっと変えてみる、そこにお客が増えるかぎがありました。\n私たちの身の回りにも、「ちょっと変えてみたらよくなる」ことがたくさんあるかもしれません。常識 {{54}} 、頭を柔らかくしておくことが大事なのです。", "passage_tr": "Siz Yaponiyadagi sushi restoranining bar peshtaxtasida «o'z xohishingiz bo'yicha» (okonomi) sushi yeb ko'rganmisiz?\nVitrindagi baliqlarni ko'rib turib, yoqtirganingizni tanlab buyurtma berasiz va yangi tayyorlab beriladi, shuning uchun eng mazali holatida yeya olasiz. Faqat qancha yeganingiz va pul miqdorini payqash qiyin bo'lgani sababli ehtiyotkorlik zarur.\nBu paytda, masalan «Maguro» deb buyurtma bersangiz, odatda 2 dona maguro sushisi keltiriladi. Nega unday? Edo davridagi sushi katta bo'lgani uchun ikkiga bo'lib berilganidan qolgan odat degan yoki hisob-kitobni osonlashtirish uchun degan turli qarashlar bor. Yakunda aniq ma'lum bo'lmay, «qadimdan shunday bo'lib kelgan» deb aytishdan boshqa chora yo'q.\nAytgancha, bunday vaziyatda 2 kishi bo'lib borsangiz yaxshi-ku, lekin 1 kishi borib 10 dona yesa, atigi 5 xil baliqni tatib ko'ra oladi, xolos. Bir aylanma sushi do'koni 1 ta likopchaga 2 xil sushidan bittadan qo'yib bera boshladi. Shunday qilinganda yegan sushi sonicha har xil sushilarni yeyish mumkinligi sababli juda ommalashdi. O'ylab ko'rsa oddiy g'oya. Biroq «qadimdan shunday bo'lgan» narsani biroz o'zgartirib ko'rish — mijozlarni jalb qilish siri shu yerda edi.\nBizning atrofimizda ham «biroz o'zgartirsa yaxshi bo'ladigan» jihatlar juda ko'p bo'lishi mumkin. Qotib qolgan tushunchalarga yopishib olmasdan, fikrlashni moslashuvchan tutish muhimdir.", "questions": [{"id": "t2-g3-50", "options": ["わかりやすいので", "わかってしまうので", "わかりづらいので", "わかりかねないので"], "answer": 3, "tr": "金額が[わかりづらいので]注意が必要です = hisob-kitob miqdorini bilish qiyin bo'lgani uchun.", "explanation_uz": "〜づらい = bilish/aniqlash mushkul", "blankNo": "50"}, {"id": "t2-g3-51", "options": ["言えるでしょう", "言いようがありません", "言いかねません", "言うまでもありません"], "answer": 2, "tr": "昔からそうなっているとしか[言いようがありません] = «qadimdan shunday» deb aytishdan boshqa so'z yo'q.", "explanation_uz": "〜ようがない = aytishning/qilishning hech bir yo'li yo'q", "blankNo": "51"}, {"id": "t2-g3-52", "options": ["a 1人 ／ b 1個ずつ ／ c 1人", "a 1人 ／ b 2個ずつ ／ c 2人", "a 2人 ／ b 1個ずつ ／ c 1人", "a 2人 ／ b 2個ずつ ／ c 1人"], "answer": 3, "tr": "2人で行けば1個ずつ食べればいいけれど、1人で行って... (2 kishi borsa 1 donadan yeydi).", "explanation_uz": "Tartib: 2人 (a) / 1個ずつ (b) / 1人 (c)", "blankNo": "52"}, {"id": "t2-g3-53", "options": ["同じすし", "たくさんのすし", "全部のすし", "いろいろなすし"], "answer": 4, "tr": "食べた寿司の数だけ[いろいろなすし]が食べられる = yeganicha har xil turlarini yeyish mumkin.", "explanation_uz": "Turli baliq turlarini tatib ko'rish haqida: いろいろなすし", "blankNo": "53"}, {"id": "t2-g3-54", "options": ["にとらわれないで", "をこわさないように", "にかかわらないで", "をぬきにして"], "answer": 1, "tr": "常識[にとらわれないで]、頭を柔らかくしておくことが大事 = qolipga yopishib qolmasdan.", "explanation_uz": "〜にとらわれる = biror tushunchaga bandi/cheklanib qolish (にとらわれないで = cheklanmasdan)", "blankNo": "54"}]}]}]}, "3": {"id": 3, "title_jp": "第3回 模擬テスト", "title_uz": "3-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t3-v1-1", "options": ["せんだく", "ぜんだく", "せんたく", "ぜんたく"], "answer": 3, "tr": "Ko'ngillilik (volontyorlik) faoliyatini tanlov fanlariga kiritayotgan universitetlar ko'paymoqda.", "stem": "ボランティア活動を【選択科目】に取り入れている大学が多くなっている。", "reading": "せんたく", "explanation_uz": "選択 → せんたく (tanlov) (選択科目 = tanlov fani)"}, {"id": "t3-v1-2", "options": ["ほうだい", "ちょうだい", "ばくだい", "じんだい"], "answer": 1, "tr": "Aeroport qurish uchun juda ulkan (behiseb) xarajat ketadi.", "stem": "飛行場を建設するには【膨大な】費用がかかる。", "reading": "ぼうだい", "explanation_uz": "膨大 → ぼうだい (ulkan, bepoyon, behad ko'p)"}, {"id": "t3-v1-3", "options": ["しょうだん", "じょだん", "じょうたん", "じょうだん"], "answer": 4, "tr": "Oddiy aytmoqchi bo'lgan hazilim do'stimning ko'nglini og'ritib qo'ydi.", "stem": "軽く言ったつもりの【冗談】が友人を傷つけてしまった。", "reading": "じょうだん", "explanation_uz": "冗談 → じょうだん (hazil, mutoyiba)"}, {"id": "t3-v1-4", "options": ["きそい", "うばい", "あらそい", "うかがい"], "answer": 2, "tr": "Shu tarzda aholi o'sishda davom etsa, butun dunyoda oziq-ovqat va suv talashuvi (tortishuvi) yuzaga kelishi mumkin.", "stem": "このまま人口が増え続ければ、世界中で食糧や水の【奪い合い】になるであろう。", "reading": "うばいあい", "explanation_uz": "奪う → うばう (tortib olmoq) (奪い合い = tortishuv, talashuv)"}, {"id": "t3-v1-5", "options": ["ぜいのう", "しょうのう", "すうのう", "せいのう"], "answer": 4, "tr": "So'nggi paytlarda jinoyatchilikdan himoyalanish xususiyati (samaradorligi) yuqori bo'lgan uylarni barpo etish rivojlanmoqda.", "stem": "最近は【防犯】性能が高いマンションや住宅を作るさまざまな取り組みが進んでいる。", "reading": "せいのう", "explanation_uz": "性能 → せいのう (ishchanlik qobiliyati, samaradorlik, unumdorlik)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t3-v2-6", "options": ["隠れた", "陰れた", "隆れた", "隔れた"], "answer": 1, "tr": "U murabbiy sportchilarning yashiringan (ichki) qobiliyatini yuzaga chiqarishda juda mohir.", "stem": "あのコーチは選手の【かくれた】能力を引き出すのがうまい。", "reading": "かくれた", "explanation_uz": "隠れる → かくれる (yashirinmoq, pinhon bo'lmoq)"}, {"id": "t3-v2-7", "options": ["計統", "形統", "系統", "経統"], "answer": 3, "tr": "Vulqon kuli elektr tizimiga (tarmoqqa) kirib borib, turli nosozliklarni keltirib chiqarishi mumkin.", "stem": "火山灰は電気けいとうに入り込み、さまざまな誤作動を起こすことがある。", "reading": "けいとう", "explanation_uz": "系統 → けいとう (tizim, tarmoq)"}, {"id": "t3-v2-8", "options": ["構想", "高層", "後送", "効相"], "answer": 2, "tr": "Bundan buyon shahar binolari tobora ko'p qavatli (baland qavatli) bo'lib borsa kerak.", "stem": "これから先、都市の建築物はますます【こうそう】化が進むであろう。", "reading": "こうそう", "explanation_uz": "高層 → こうそう (baland qavatli, osmono'par)"}, {"id": "t3-v2-9", "options": ["解倣", "解封", "解報", "解放"], "answer": 4, "tr": "Inson butun umr tashvishlardan aslo qutulolmasa (ozod bo'lolmasa) kerak deb o'ylayman.", "stem": "人間は一生悩むことから【かいほう】されないのだと思う。", "reading": "かいほう", "explanation_uz": "解放 → かいほう (ozod bo'lish, qutulish)"}, {"id": "t3-v2-10", "options": ["並べて", "比べて", "列べて", "対べて"], "answer": 2, "tr": "Sabzavot va mevalarning to'yimlilik darajasi ilgarigisi bilan solishtirganda pasayib bormoqda.", "stem": "野菜や果物の栄養価は昔のものと【くらべて】低くなっている。", "reading": "くらべて", "explanation_uz": "比べる → くらべる (solishtirmoq, taqqoslamoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t3-v3-11", "options": ["多", "複", "重", "諸"], "answer": 4, "tr": "Turli holatlar (sabablar) tufayli ushbu tadbir bekor qilinadi.", "stem": "（　）事情により今回のイベントは中止する。", "explanation_uz": "諸事情 (しょじじょう) = turli sabablar/sharoitlar"}, {"id": "t3-v3-12", "options": ["日", "泊", "行", "出"], "answer": 1, "tr": "Yakshanba kuni oilaviy bir kunlik (borib-kelinadigan) sayohatdan zavqlandik.", "stem": "日曜日は家族で（　）帰りの旅行を楽しんだ。", "explanation_uz": "日帰り (ひがえり) = bir kunlik sayohat (tunab qolmasdan qaytish)"}, {"id": "t3-v3-13", "options": ["末", "来", "数", "真"], "answer": 2, "tr": "Yo'l qurilishi kelasi (moliyaviy) yildan boshlanadi.", "stem": "道路工事は（　）年度から始まる。", "explanation_uz": "来年度 (らいねんど) = kelasi moliyaviy/o'quv yili"}, {"id": "t3-v3-14", "options": ["風", "式", "的", "性"], "answer": 3, "tr": "Eng zamonaviy uskunalar bilan jihozlangan zamonaviy bino qad ko'tardi.", "stem": "最新の機器を備えた近代（　）なビルが建設された。", "explanation_uz": "近代的 (きんだいてき) = zamonaviy uslubdagi"}, {"id": "t3-v3-15", "options": ["感", "性", "化", "風"], "answer": 2, "tr": "Doim aniq-tiniq savollar beradigan bu yigitda kelajak porloqligini (potensialni) his qilaman.", "stem": "的確な質問をよくしてくる彼には将来（　）を感じる。", "explanation_uz": "将来性 (しょうらいせい) = istiqbol, kelajak imkoniyatlari"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t3-v4-16", "options": ["せいぜい", "そろそろ", "ゆうゆう", "まあまあ"], "answer": 4, "tr": "Imtihon qanday o'tdimi? Juda zo'r bo'lmadi-yu, ammo o'rtacha (yomon emas) bo'ldi deb o'ylayman.", "stem": "試験の出来ですか。すごくよくはなかったけど（　）だったと思います。", "explanation_uz": "まあまあ = o'rtacha, durustgina, qoniqarli"}, {"id": "t3-v4-17", "options": ["例える", "比べる", "たたえる", "こたえる"], "answer": 1, "tr": "Uni hayvonga qiyoslasak (o'xshatsak), injiq fe'l-atvori mushukka o'xshaydi.", "stem": "彼女を動物に（　）と、気まぐれなところがネコっぽいね。", "explanation_uz": "例える (たとえる) = o'xshatmoq, qiyoslamoq"}, {"id": "t3-v4-18", "options": ["評判", "結論", "誤解", "決定"], "answer": 3, "tr": "Har narsani darrov amalga oshiradigan u kishini hovliqma odam deb noto'g'ri tushunishadi (adashishadi).", "stem": "なんでもすぐ行動に移す彼は、気が短い人間だと（　）されている。", "explanation_uz": "誤解 (ごかい) = noto'g'ri tushunish, yanglish xulosa"}, {"id": "t3-v4-19", "options": ["不利", "不幸", "地味", "粗末"], "answer": 4, "tr": "Ilgari zodagonlardan tashqari kambag'al insonlar kichik va abgor (oddiy/g'aribona) uylarda yashashgan.", "stem": "昔は貴族以外のまずしい人々は、小さくて（　）な家に住んでいた。", "explanation_uz": "粗末 (そまつ) = oddiy, g'aribona, abgor"}, {"id": "t3-v4-20", "options": ["オープン", "フレッシュ", "ダイレクト", "ショック"], "answer": 2, "tr": "Yangi ishga kirgan xodimlar yangicha, jo'shqin (fresh) jozibaga to'ladir.", "stem": "新入社員は、（　）な魅力にあふれている。", "explanation_uz": "フレッシュ (fresh) = yangi, jo'shqin, navqiron"}, {"id": "t3-v4-21", "options": ["持ち", "造り", "取り", "兼ね"], "answer": 4, "tr": "Bu sport poyabzali yurishga qulaylik va chiroyli dizaynni o'zida birgalikda mujassam etgan.", "stem": "この運動靴は歩きやすさとデザインのよさを（　）備えている。", "explanation_uz": "兼ね備える (かねそなえる) = o'zida ikkala xususiyatni ham jamlamoq"}, {"id": "t3-v4-22", "options": ["季節品", "必需品", "付属品", "消耗品"], "answer": 2, "tr": "Ushbu savdo ko'chasida hayot uchun zarur barcha kundalik ehtiyoj mollari topiladi.", "stem": "この商店街で生活（　）はすべてそろう。", "explanation_uz": "生活必需品 (せいかつひつじゅひん) = hayotiy zarur vositalar/tovarlar"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t3-v5-23", "options": ["考えなしに", "思いっきり", "絶えず", "大量に"], "answer": 1, "tr": "Opam keraksiz narsalargacha o'ylab-netmasdan (ketma-ket, pala-partish) sotib olaveradi.", "stem": "姉はいらないものまで【やたらに】買い込んでしまう。", "reading": "やたらに", "explanation_uz": "やたらに = 考えなしに (o'ylamasdan, duch kelganicha)"}, {"id": "t3-v5-24", "options": ["余裕", "夢", "油断", "特徴"], "answer": 3, "tr": "U aslo bo'shashmaydigan (g'ofillik qilmaydigan, ehtiyotkor) inson.", "stem": "彼女は【隙のない】人だ。", "reading": "すきのない", "explanation_uz": "隙のない = 油断がない (ehtiyotkor, hushyor)"}, {"id": "t3-v5-25", "options": ["容易に", "計画的に", "注意深く", "素早く"], "answer": 3, "tr": "Yangi qonun loyihasini ishlab chiqishni ehtiyotkorlik bilan (sinchiklab) olib bormoqda.", "stem": "新しい法案作りを【慎重に】進める。", "reading": "しんちょうに", "explanation_uz": "慎重に → 注意深く (diqqat va ehtiyotkorlik bilan)"}, {"id": "t3-v5-26", "options": ["質問された", "称賛された", "注目された", "非難された"], "answer": 4, "tr": "Avariya keltirib chiqargan kompaniya rahbari OAV tomonidan qattiq tanqid qilindi (qoralandi).", "stem": "事故を起こした会社の社長はマスコミに【叩かれた】。", "reading": "たたかれた", "explanation_uz": "叩く (たたく) = 非難された (tanqid qilinmoq, qoralanmoq)"}, {"id": "t3-v5-27", "options": ["新しい", "めずらしい", "高い", "すばらしい"], "answer": 2, "tr": "Bu gitara cheklangan miqdorda chiqarilgan noyob (kamyob) buyumdir.", "stem": "このギターは限定生産の【レアな】ものだ。", "explanation_uz": "レアな (rare) = めずらしい (noyob, kamyob)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t3-v6-28", "options": ["この祭りは自然の恩恵に浴する感謝を表している。", "お世話になった人に恩恵返しをする。", "この神社のお守りは恩恵があると評判だ。", "先生の恩恵で、無事卒業することができた。"], "answer": 1, "tr": "恩恵 (おんけい) = inoyat, ne'mat, foyda/naf.", "stem": "恩恵", "optsTr": ["Bu festival tabiat ne'matlaridan bahramand bo'lganlik minnatdorchiligini bildiradi. (to'g'ri)", "Qaragan odamga 'ne'mat qaytaraman' (noto'g'ri — 恩返し).", "Bu tumor 'ne'matli' (noto'g'ri — ご利益).", "Ustozning 'ne'mati' bilan bitirdim (noto'g'ri — おかげ)."]}, {"id": "t3-v6-29", "options": ["税金が上がって、素人の生活は苦しくなった。", "これはとても素人には作れない料理だ。", "どこの素人かわからない男に娘を嫁にやるわけにはいかない。", "彼女は素人だけあって、とても美しい。"], "answer": 2, "tr": "素人 (しろうと) = havaskor, nohaqiqiy mutaxassis.", "stem": "素人", "optsTr": ["Soliq oshib, 'havaskorlar' turmushi qiyinlashdi (noto'g'ri — 庶民).", "Bu taomni havaskor (oddiy odam) aslo tayyorlay olmaydi. (to'g'ri)", "Qaysi 'havaskor' ekani noma'lum yigitga qizimni bermayman (noto'g'ri — 馬の骨).", "U 'havaskor' bo'lgani uchun chiroyli (noto'g'ri)."]}, {"id": "t3-v6-30", "options": ["夫に家事を手伝ってもらったが、ちょっとだらしない。", "こんなつまらない仕事、だらしなくてやっていられない。", "そんなことで落ちこむなんて、だらしないやつだ。", "彼女はきちんと家計簿をつけていて、とてもお金にだらしない。"], "answer": 3, "tr": "だらしない = irodasiz, bo'sh, o'zini tutolmaydigan, betartib.", "stem": "だらしない", "optsTr": ["Erim yordam berdi, lekin 'irodasiz' (noto'g'ri).", "Bunday zerikarli ishda 'irodasiz bo'lib' ishlab bo'lmaydi (noto'g'ri — ばかばかしい).", "Shunaqa arzimagan narsaga tushkunlikka tushadigan bo'sh, irodasiz ekansan-a! (to'g'ri)", "U hisob-kitobni aniq yuritadi va pulga 'pala-partish' (noto'g'ri — ziddiyat)."]}, {"id": "t3-v6-31", "options": ["日本では、話すことより読む勉強に重点を置く学校がいまだ多い。", "この計画の成功の重点は君の活躍にかかっている。", "彼は長年財界の重点だった。", "あの作家の重点のある言葉が気に入っている。"], "answer": 1, "tr": "重点 (じゅうてん) = asosiy e'tibor, urg'u (重点を置く).", "stem": "重点", "optsTr": ["Yaponiyada gapirishdan ko'ra o'qishga ko'proq urg'u beradigan (e'tibor qaratadigan) maktablar hali ham ko'p. (to'g'ri)", "Muvaffaqiyatning 'asosiy e'tibori' senga bog'liq (noto'g'ri — 鍵).", "U moliyaviy sohaning 'urg'usi' edi (noto'g'ri — 重鎮).", "Yozuvchining 'urg'uli' so'zlari (noto'g'ri — 重み)."]}, {"id": "t3-v6-32", "options": ["このコース修了者には資格を支給する。", "客は店員に品物の代金を現金で支給した。", "海外旅行をするなら旅券の支給手続きをしてください。", "この会社は、給料のほかに家族手当が支給される。"], "answer": 4, "tr": "支給 (しきゅう) = to'lab berish, beriladigan nafaqa/to'lov.", "stem": "支給", "optsTr": ["Kursni bitirganlarga malaka 'to'lanadi' (noto'g'ri — 付与/授与).", "Mijoz tovarni naqd pulda 'to'lab berdi' (noto'g'ri — 支払う).", "Pasportni 'to'lash' arizasi (noto'g'ri — 発行).", "Bu kompaniyada oylikdan tashqari oilaviy nafaqa ham to'lab beriladi (beriladi). (to'g'ri)"]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t3-g1-33", "options": ["上から", "上で", "上に", "上は"], "answer": 4, "tr": "Bir marta ishni zimmangga olgan ekansan, nima bo'lsa ham oxiriga yetkazishing shart.", "stem": "いったん仕事を引き受けた（　）、何があっても完成させなければならない。", "explanation_uz": "〜上は (うえは) = ...ekansan / modomiki ... qilar ekansan (qatiy burch)"}, {"id": "t3-g1-34", "options": ["せいで", "くせに", "ものの", "おかげで"], "answer": 4, "tr": "Hamyonimni unutib qoldirgan bo'lsam-da, kredit kartam borligi sharofati bilan arang xarid qila oldim.", "stem": "財布を忘れたが、クレジットカードを持っていた（　）、何とか買い物ができた。", "explanation_uz": "〜おかげで = ...ning sharofati / yaxshiligi tufayli"}, {"id": "t3-g1-35", "options": ["のことから", "のことだから", "のこととはいえ", "のことにしては"], "answer": 2, "tr": "Xasis bo'lgan u kishini bilganimiz uchun, asl brilliant sotib olishi aslo mumkin emas.", "stem": "けちな彼女（　）、本物のダイヤモンドなんか買うはずがない。", "explanation_uz": "〜のことだから = ...ning fe'lini bilganimiz sababli"}, {"id": "t3-g1-36", "options": ["以前では", "次第では", "程度では", "事情では"], "answer": 2, "tr": "A kompaniyasi raqib bo'lsa-da, shartlarga qarab birlashish muzokaralarini olib borsa bo'ladi.", "stem": "A社はライバルだが、条件（　）は合併の交渉をしてもよい。", "explanation_uz": "〜次第では (しだいでは) = ...ga qarab, holatga bog'liq ravishda"}, {"id": "t3-g1-37", "options": ["に応じて", "に向かって", "に備えて", "に関して"], "answer": 3, "tr": "Katta zilzilaga tayyorgarlik ko'rib, xarita orqali uygacha qaytish yo'lini tekshirib qo'yaylik.", "stem": "大地震（　）、地図で家までの帰り道を確認しておこう。", "explanation_uz": "〜に備えて (にそなえて) = ...ga tayyorgarlik ko'rish maqsadida"}, {"id": "t3-g1-38", "options": ["だけでは", "ぬきには", "ほどには", "のみでは"], "answer": 2, "tr": "«Gilos gulladi» deb yangiliklarda aytiladigan darajada, Yaponiyaning bahorini sakurasiz tasavvur etib (gapirib) bo'lmaydi.", "stem": "「さくらが咲いた」とニュースになるくらい、日本の春はさくら（　）語れない。", "explanation_uz": "〜ぬきには = ...siz, ...bo'lmasa (amalga oshmaydi)"}, {"id": "t3-g1-39", "options": ["はずされておりますので", "はずしていらっしゃいますので", "はずしておりますので", "はずしてしまいますので"], "answer": 3, "tr": "A: «Allo, Yamashita prezident shu yerdamilar?»\nB: «Hozir joylarida yo'q edilar (席を外しております), qayta qo'ng'iroq qildiraman.»", "stem": "A「もしもし、山下社長はいらっしゃいますか。」\nB「ただいま、席を（　）、折り返しご連絡差し上げます。」", "explanation_uz": "席を外しております = joyida yo'q (kamtarin nutq / kenjougo)"}, {"id": "t3-g1-40", "options": ["間に合いそうもない", "間に合わないはずがない", "間に合うわけでもない", "間に合うほかない"], "answer": 1, "tr": "Shoshib maqola yozyapman, ammo bunday ketishda muddatiga aslo ulgura olmasam kerak.", "stem": "急いで論文を書いているが、このままでは締め切りには（　）。", "explanation_uz": "〜そうもない = ulgura oladiganga o'xshamaydi (ehtimoli juda kam)"}, {"id": "t3-g1-41", "options": ["知っていただけに", "知らなかっただけに", "知っていたばかりに", "知らなかったばかりに"], "answer": 4, "tr": "Men bu yerdagi qoidani bilmaganim oqibatidagina barchangizga tashvish tug'dirdim.", "stem": "私がここの決まりを（　）、みなさんにご迷惑をおかけしました。", "explanation_uz": "〜ばかりに = faqatgina ... tufayli (yomon natija keltirib chiqardi)"}, {"id": "t3-g1-42", "options": ["人がいるはずだ", "人はいないはずだ", "人がいるということだ", "人がいないということだ"], "answer": 2, "tr": "Agar siz og'iz ochmasangiz, bu ishni biladigan hech kim bo'lmasligi kerak.", "stem": "あなたがしゃべらない限り、このことを知っている（　）。", "explanation_uz": "〜はずだ = ...bo'lishi aniq/tabiiy (知っている人はいないはずだ)"}, {"id": "t3-g1-43", "options": ["おいしいはずで", "おいしいわけではなく", "おいしくないはずで", "おいしくないわけではなく"], "answer": 2, "tr": "Taom qancha yangi bo'lsa shuncha mazali bo'ladi degani emas, biroz saqlangani shirinroq bo'ladigan ozuqalar ham bor.", "stem": "食べ物は新鮮であればあるほど（　）、少し古いほうがおいしい食品もある。", "explanation_uz": "〜わけではなく = mutlaqo shunday degani emas"}, {"id": "t3-g1-44", "options": ["つぐわけではない", "つがないではいられない", "ついではならない", "つがざるを得ない"], "answer": 1, "tr": "Zamonaviy Yaponiyada to'ng'ich o'g'il bo'lgani bilan oila vorisligini olishi shart emas.", "stem": "現代の日本では、長男だからといって必ず家を（　）。", "explanation_uz": "〜わけではない = doim ham shart/shunday degani emas"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t3-g2-45", "options": ["助けて", "しては", "いるなら", "私と"], "answer": 2, "tr": "To'g'ri tartib: あなたが困っているなら、私としては助けてあげたいのだが……。", "explanation_uz": "To'g'ri tartib: 困って[いるなら][私と][★しては][助けて] (3 → 4 → 2 → 1)", "prefix": "あなたが困って", "suffix": "あげたいのだが……。", "starPos": 2, "order": [3, 4, 2, 1]}, {"id": "t3-g2-46", "options": ["平気", "10円を", "一方で", "節約する"], "answer": 3, "tr": "To'g'ri tartib: 私の妻は10円を節約する一方で、平気で高い服を買うことがある。", "explanation_uz": "To'g'ri tartib: 妻は[10円を][節約する][★一方で][平気] (2 → 4 → 3 → 1)", "prefix": "私の妻は", "suffix": "で高い服を買うことがある。", "starPos": 3, "order": [2, 4, 3, 1]}, {"id": "t3-g2-47", "options": ["もちろん", "甘すぎないので", "女性は", "男性に"], "answer": 1, "tr": "To'g'ri tartib: この店のケーキは甘すぎないので女性はもちろん、男性にも人気がある。", "explanation_uz": "To'g'ri tartib: [甘すぎないので][女性は][★もちろん][男性に] (2 → 3 → 1 → 4)", "prefix": "この店のケーキは", "suffix": "も人気がある。", "starPos": 3, "order": [2, 3, 1, 4]}, {"id": "t3-g2-48", "options": ["こと", "また", "どこか", "だから"], "answer": 4, "tr": "To'g'ri tartib: 時間にだらしない山下さんのことだから、またどこかでさぼっているのだろう。", "explanation_uz": "To'g'ri tartib: 山下さんの[こと][★だから][また][どこか] (1 → 4 → 2 → 3)", "prefix": "時間にだらしない山下さんの", "suffix": "でさぼっているのだろう。", "starPos": 2, "order": [1, 4, 2, 3]}, {"id": "t3-g2-49", "options": ["流れに", "進むと", "沿って", "歩く"], "answer": 3, "tr": "To'g'ri tartib: 人の歩く流れに沿って進むと、その先にイベント会場があった。", "explanation_uz": "To'g'ri tartib: 人の[歩く][流れに][★沿って][進むと] (4 → 1 → 3 → 2)", "prefix": "人の", "suffix": "その先にイベント会場があった。", "starPos": 3, "order": [4, 1, 3, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "父子家庭への支援", "passage": "妻と離婚、または死別して20歳以下の子どもを育てている男性の家庭を「父子家庭」と言います（これに対し、母親と児童の家庭を「母子家庭」と言います）。最近の20年、離婚の増加により父子家庭の数は過去最高になりました。\n母子家庭には、その収入 {{50}} 、児童扶養手当という子どもを育てるためのお金が支給され、ほかにもさまざまな制度があります。日本は「夫が外でお金を稼ぎ、妻が家庭で家事・育児をする」という考えが強かったので、 {{51-a}} は経済的に苦しい家が多かったためです。\n一方、「 {{51-b}} と比べて {{51-c}} には経済的な問題はないだろう」と思われていたので、児童扶養手当は支給されていませんでした。\nところが父子家庭の収入は、母子家庭ほど {{52}} 、平均に比べたらずいぶん低いことがわかりました。 {{53}} 、日本では男性は長い残業も休日出勤もやるのが当たり前で、「保育園に子どもを迎えに行くから、5時には帰らなければならない」という男性を雇ってくれる会社は、あまり多くないのです。すでに働いていても、正社員でなくアルバイトになったり、男性であっても、 {{54}} 。\nそして、厚生労働省は低収入の父子家庭にも児童扶養手当を支給することを決定しました。この制度は2010年の年末から施行されることになり、約10万所帯が給付の対象になります。", "passage_tr": "Xotini bilan ajrashgan yoki xotini vafot etib, 20 yoshdan kichik bolani tarbiyalayotgan erkakning oilasi «otasiz oila» (fusikatei) deb ataladi. So'nggi 20 yilda ajrimlar ko'payishi bilan bunday oilalar soni tarixdagi eng yuqori darajaga yetdi.\nOnalik oilalariga ularning daromadiga qarab bola tarbiyasi nafaqasi to'lanadi. Yaponiyada «er tashqarida pul topadi, ayol esa uyda ro'zg'or va bola tarbiyasi bilan shug'ullanadi» degan tushuncha kuchli bo'lgani sababli, onalik oilalari moddiy jihatdan qiynalgan oilalar ko'p bo'lgan.\nBoshqa tomondan esa «onali oilalarga nisbatan otali oilalarda iqtisodiy muammo bo'lmasa kerak» deb hisoblangani bois, bolalar nafaqasi berilmas edi.\nVaholanki otali oilalarning daromadi onalarnikidek past bo'lmasa ham, o'rtacha ko'rsatkichdan ancha pastligi ma'lum bo'ldi. Buning ustiga, Yaponiyada erkaklar uzoq vaqt qo'shimcha ishlashi va dam olish kunlari ham ishlashi tabiiy hol bo'lib, «bolani bog'chadan olishim kerak, soat 5 da ketishim shart» degan erkakni ishga oladigan kompaniyalar juda kam. Hatto ishlab turgan bo'lsa ham, doimiy emas, balki soatbay ishchiga aylanib qolishadi.\nShuning uchun Sog'liqni saqlash vazirligi kam ta'minlangan otali oilalarga ham bolalar nafaqasini to'lashga qaror qildi.", "questions": [{"id": "t3-g3-50", "options": ["に伴った", "に応じた", "に比べた", "に沿った"], "answer": 2, "tr": "その収入[に応じた]児童扶養手当 = o'sha daromadiga mos keladigan nafaqa.", "explanation_uz": "〜に応じた (におうじた) = ...ga mos, muvofiq", "blankNo": "50"}, {"id": "t3-g3-51", "options": ["a 父子家庭 ／ b 母子家庭 ／ c 母子家庭", "a 父子家庭 ／ b 父子家庭 ／ c 母子家庭", "a 母子家庭 ／ b 母子家庭 ／ c 父子家庭", "a 母子家庭 ／ b 父子家庭 ／ c 父子家庭"], "answer": 3, "tr": "a 母子家庭 (onali oila) qiynalgan; b 母子家庭 ga qaraganda c 父子家庭 da muammo yo'q deb o'ylangan.", "explanation_uz": "Tartib: a 母子家庭 / b 母子家庭 / c 父子家庭", "blankNo": "51"}, {"id": "t3-g3-52", "options": ["低いにしても", "低いわけがなく", "低くはないものの", "低いと思ったら"], "answer": 3, "tr": "母子家庭ほど[低くはないものの]、平均に比べたらずいぶん低い = unchalik past bo'lmasa-da, o'rtachadan ancha past.", "explanation_uz": "〜ものの = ...bo'lsa-da, qaramasdan", "blankNo": "52"}, {"id": "t3-g3-53", "options": ["というのも", "だからといって", "にもかかわらず", "とはいえ"], "answer": 1, "tr": "[というのも]、日本では男性は長い残業もやるのが当たり前で = Negaki, Yaponiyada...", "explanation_uz": "というのも = sababi shundaki, negaki", "blankNo": "53"}, {"id": "t3-g3-54", "options": ["高収入になりかねません", "高収入にならざるを得ません", "低収入になり得ないのです", "低収入になり得るのです"], "answer": 4, "tr": "男性であっても、[低収入になり得るのです] = Erkak kishi bo'lsa ham kam daromadli bo'lib qolishi mumkin.", "explanation_uz": "〜得る (うる) = bo'lishi mumkin, ehtimoli bor", "blankNo": "54"}]}]}]}, "4": {"id": 4, "title_jp": "第4回 模擬テスト", "title_uz": "4-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t4-v1-1", "options": ["いわゆる", "あらゆる", "いたる", "とおる"], "answer": 3, "tr": "Robotlar fabrikalarda-ku mayli, Xalqaro kosmik stansiyagacha — har bir yerda (hamma joyda) qo'llanilmoqda.", "stem": "ロボットは、工場はもちろん国際宇宙ステーションまで、【至る所】で使われている。", "reading": "いたる", "explanation_uz": "至る所 → いたるところ (hamma joyda, har burchakda)"}, {"id": "t4-v1-2", "options": ["わりひき", "わりびき", "かつひき", "かつびき"], "answer": 2, "tr": "10 kun oldin band qilsangiz, erta chegirma (skidka) bilan mehmonxona narxi arzonlashadi.", "stem": "10日前までに予約をすると、早期【割引】で宿泊料金が安くなる。", "reading": "わりびき", "explanation_uz": "割引 → わりびき (chegirma, skidka)"}, {"id": "t4-v1-3", "options": ["はっそう", "はつそう", "ほっそう", "はつぞう"], "answer": 1, "tr": "Stol atrofida o'tirgandan ko'ra, sayr qilayotganda ish bo'yicha yangi g'oyalar quyilib kelishi ko'proq uchraydi.", "stem": "机に向かっているときより、散歩中に仕事の【発想】がわいてくることが多い。", "reading": "はっそう", "explanation_uz": "発想 → はっそう (g'oya, fikr uyg'onishi)"}, {"id": "t4-v1-4", "options": ["かんがく", "かんかく", "がんかく", "がんがく"], "answer": 2, "tr": "Pul qadrini his qilmaydigan (isrofgar) otam tufayli onam uzoq vaqt qiynalib yashagan.", "stem": "金銭感覚のなかった父に、母はずっと苦労させられていた。", "reading": "かんかく", "explanation_uz": "感覚 → かんかく (hissiyot, sezgi)"}, {"id": "t4-v1-5", "options": ["じんじゅう", "しんじゅう", "じんちょう", "しんちょう"], "answer": 4, "tr": "Nikoh inson umrining muhim voqeasi bo'lgani sababli, ehtiyotkorlik (vazminlik) bilan o'yla.", "stem": "結婚は人生の一大事だから【慎重】に考えなさい。", "reading": "しんちょう", "explanation_uz": "慎重 → しんちょう (ehtiyotkor, vazmin, puxta)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t4-v2-6", "options": ["吸集", "究収", "吸収", "急就"], "answer": 3, "tr": "U bola xuddi gubka (sponj) kabi o'rgatilgan barcha narsani o'ziga singdirib (yutib) oladi.", "stem": "あの子はまるでスポンジのように教えたことはすべて【きゅうしゅう】する。", "reading": "きゅうしゅう", "explanation_uz": "吸収 → きゅうしゅう (singdirish, shimib olish)"}, {"id": "t4-v2-7", "options": ["滞存", "滞在", "帯存", "帯在"], "answer": 2, "tr": "U olim ushbu orolda uzoq muddat yashab (turib), o'simliklarni tadqiq qilmoqda.", "stem": "あの学者は、この島に長期【たいざい】して、植物の研究をしている。", "reading": "たいざい", "explanation_uz": "滞在 → たいざい (vaqtincha istiqomat qilish, turish)"}, {"id": "t4-v2-8", "options": ["因む", "図む", "回む", "囲む"], "answer": 4, "tr": "Oila a'zolari birgalikda dasturxon atrofida jamlanishi (o'tirishi) kamayib ketdi.", "stem": "家族みんなで食卓を【かこむ】ことが少なくなってしまった。", "reading": "かこむ", "explanation_uz": "囲む → かこむ (o'rab olmoq, atrofida o'tirmoq)"}, {"id": "t4-v2-9", "options": ["安意", "安易", "案意", "案易"], "answer": 2, "tr": "Qizim reklamadagi fikrlarga osongina (yengil-yelpi) ishonib, qimmatbaho qo'shimchalarni sotib olaveradi.", "stem": "娘はチラシの体験談を【あんい】に信じて高いサプリメントをよく買っている。", "reading": "あんい", "explanation_uz": "安易 → あんい (yengil-yelpi, osongina)"}, {"id": "t4-v2-10", "options": ["嗅ぎ", "咲ぎ", "喝ぎ", "喫ぎ"], "answer": 1, "tr": "Xizmat iti yuk mashinasi ichidagi portlovchi moddani hidlab topdi.", "stem": "警察犬はトラックの中の爆発物を【かぎ】あてた。", "reading": "かぎ", "explanation_uz": "嗅ぐ → かぐ (hidlamoq, hid bilmoq)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t4-v3-11", "options": ["無", "不", "非", "反"], "answer": 3, "tr": "Tunning yarmida baland ovozda baqirib shovqin solish — beodoblikdir (aqlsizlikdir).", "stem": "夜中に大声で騒ぐなんて（　）常識だ。", "explanation_uz": "非常識 (ひじょうしき) = odobsizlik, madaniyatsizlik"}, {"id": "t4-v3-12", "options": ["悪", "非", "無", "不"], "answer": 4, "tr": "Bo'lim boshlig'i kun bo'yi xomush (kayfiyatsiz) yurdi.", "stem": "部長は1日中（　）機嫌だった。", "explanation_uz": "不機嫌 (ふきげん) = kayfiyatsiz, jahldor holat"}, {"id": "t4-v3-13", "options": ["化", "出", "下", "現"], "answer": 1, "tr": "Ikki kishining fikr qarama-qarshiligi yuzaga chiqadi (oshkor bo'ladi).", "stem": "2人の意見の対立が表面（　）する。", "explanation_uz": "表面化 (ひょうめんか) = oshkoralashish, yuzaga chiqish"}, {"id": "t4-v3-14", "options": ["性", "量", "率", "比"], "answer": 3, "tr": "Bu galgi saylovda qatnashish foizi (davomat ko'rsatkichi) yuqori bo'ldi.", "stem": "今回の選挙の投票（　）は高かった。", "explanation_uz": "投票率 (とうひょうりつ) = saylovda qatnashish foizi / davomat ko'rsatkichi"}, {"id": "t4-v3-15", "options": ["和", "家", "新", "手"], "answer": 4, "tr": "O'z qo'lim bilan tayyorlagan taomni do'stimga mehmon qilib tortiq qilaman.", "stem": "（　）料理を友人にふるまう。", "explanation_uz": "手料理 (てりょうり) = o'z qo'li bilan tayyorlagan taom"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t4-v4-16", "options": ["展開", "事情", "事態", "体制"], "answer": 2, "tr": "Tabiiy gazdan foydalanish butun dunyodagi energiya holatini (vaziyatini) o'zgartirsa kerak.", "stem": "天然ガスの利用は世界のエネルギー（　）を変えるであろう。", "explanation_uz": "エネルギー事情 (エネルギーじじょう) = energetika vaziyati/holati"}, {"id": "t4-v4-17", "options": ["フィット", "セット", "マット", "カット"], "answer": 1, "tr": "Qaddi-qomati kichik onam tanasiga mos tushadigan (fit bo'ladigan) kiyim topishga doim qiynaladi.", "stem": "小柄な母は体に（　）する服を探すのにいつも苦労している。", "explanation_uz": "フィットする (fit) = mos tushmoq, loyiq kelmoq"}, {"id": "t4-v4-18", "options": ["耕して", "稼いで", "整って", "扱って"], "answer": 4, "tr": "Ekin ekish tirik jon bilan muomala qilish (parvarishlash) bo'lgani sababli, suv quyishni kelasi haftaga qoldirib bo'lmaydi.", "stem": "畑作りは生きている命を（　）いるので、今週は忙しいから、水やりは来週というわけにはいかない。", "explanation_uz": "扱う (あつかう) = muomala qilmoq, parvarishlamoq"}, {"id": "t4-v4-19", "options": ["あくまでも", "おそらく", "いわゆる", "ほとんど"], "answer": 1, "tr": "Bu faqatgina (qat'iy qilib aytganda) mening shaxsiy fikrim, xolos. Boshqalar boshqacha fikrda bo'lsa kerak.", "stem": "これは（　）私の意見にすぎません。他の人はたぶん違う意見だと思います。", "explanation_uz": "あくまでも = faqatgina, mutlaqo (あくまでも〜にすぎない)"}, {"id": "t4-v4-20", "options": ["援助", "失敗", "文句", "遠慮"], "answer": 4, "tr": "Fikringiz bo'lsa, hech qanday tortinishsiz (uyalmasdan) menga aytavering.", "stem": "意見があれば何でも（　）なく私に言ってください。", "explanation_uz": "遠慮なく (えんりょなく) = tortinmasdan, bemalol"}, {"id": "t4-v4-21", "options": ["ちからづよく", "そそっかしく", "ずうずうしく", "くだらなく"], "answer": 3, "tr": "Uzun navbatning o'rtasiga bir ayol surbetlarcha (uyalmasdan) suqilib kirdi.", "stem": "長い行列の真ん中に、1人の女性が（　）割り込んできた。", "explanation_uz": "ずうずうしく = surbetlarcha, yuzsizlarcha"}, {"id": "t4-v4-22", "options": ["改良", "補助", "改正", "統制"], "answer": 3, "tr": "Qonun qayta ko'rib chiqilib (o'zgartirilib), soyabon ushlagan holda velosiped haydash taqiqlandi.", "stem": "法律が（　）され、傘を差したまま自転車に乗るのは禁止された。", "explanation_uz": "改正 (かいせい) = qonun yoki qoidani o'zgartirish/tuzatish"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t4-v5-23", "options": ["とても困る", "予定が狂う", "頭に来る", "不安だ"], "answer": 1, "tr": "Oylik olish oldidan to'satdan chiqqan xarajat juda qiyin (juda noqulay, ziyonli).", "stem": "給料前の急な出費は【痛い】。", "reading": "いたい", "explanation_uz": "痛い = とても困る (juda qiyin, noqulay, og'ir botadi)"}, {"id": "t4-v5-24", "options": ["続いて", "影響して", "戻って", "ひどくて"], "answer": 2, "tr": "Bahor boshidagi sovuq havo ta'sir qilib, sabzavotlar narxi ko'tarildi.", "stem": "春先の低温が【響き】、野菜の値段が高くなった。", "reading": "ひびき", "explanation_uz": "響く → 影響して (ta'sir qilmoq, oqibat keltirmoq)"}, {"id": "t4-v5-25", "options": ["毎回", "お互いに", "各自", "常に"], "answer": 3, "tr": "O'z yukingizga har bir kishi o'zi (alohida-alohida) hushyor bo'lsin.", "stem": "自分の荷物は【めいめいで】気をつけてください。", "reading": "めいめいで", "explanation_uz": "めいめいで = 各自 (かくじ — har bir kishi o'zi alohida)"}, {"id": "t4-v5-26", "options": ["障害", "仕事", "苦労", "心配"], "answer": 1, "tr": "Ayollarning jamiyatda faol bo'lishida bola parvarishi kabi katta to'siq (g'ov) mavjud.", "stem": "女性の社会進出には子育てという大きな【壁】がある。", "reading": "かべ", "explanation_uz": "壁 = 障害 (しょうがい — to'siq, g'ov)"}, {"id": "t4-v5-27", "options": ["週末", "昼休み", "祝日", "休みの日"], "answer": 4, "tr": "Dam olish kunlarini (off) asosan televizor ko'rib o'tkazaman.", "stem": "オフは【もっぱら】テレビを見て過ごす。", "explanation_uz": "オフ = 休みの日 (dam olish kuni)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t4-v6-28", "options": ["私どもの協会は何よりも自由と平等を演説しております。", "選挙中、声を限りに候補者の名前を演説した。", "新しい首相は、政策について国会で演説した。", "あの男は義務も果たさずに権利ばかり演説する。"], "answer": 3, "tr": "演説 (えんぜつ) = nutq so'zlash (siyosiy, ommaviy nutq).", "stem": "演説", "optsTr": ["Assotsiatsiyamiz ozodlikni 'nutq so'zlaydi' (noto'g'ri — 主張).", "Saylovda nomzod ismini 'nutq so'zladi' (noto'g'ri — 連呼).", "Yangi bosh vazir siyosiy rejalari haqida parlamentda nutq so'zladi. (to'g'ri)", "U majburiyatni bajarmay, faqat huquqlarni 'nutq so'zlaydi' (noto'g'ri)."]}, {"id": "t4-v6-29", "options": ["あなたの生まれは何月何日ですか。", "彼のあのがんこさは生まれのものでどうにもならない。", "乳歯から永久歯の生まれは10歳ぐらいに起きる。", "彼女は生まれがよいのか、どこか品がある。"], "answer": 4, "tr": "生まれ (うまれ) = nasl-nasab, kelib chiqish muhiti.", "stem": "生まれ", "optsTr": ["Tug'ilgan kuningiz qachon (noto'g'ri — 生年月日).", "Uning o'jarligi tug'ma (noto'g'ri — 生まれつき).", "Sut tishidan doimiy tishga almashish (noto'g'ri — 生え変わり).", "Uning nasl-nasabi (kelib chiqishi) yaxshi bo'lgani sabablimi, o'zida bir olijanoblik bor. (to'g'ri)"]}, {"id": "t4-v6-30", "options": ["最近子どもの様子が少し危うい。", "近所を危うい男がうろうろしている。", "この道路は夜とても暗いので、1人で歩くのは危うい。", "おぼれかけたが、危ういところで助けられた。"], "answer": 4, "tr": "危うい (あやうい) = xatarli, qilt ustida qolgan (危ういところで = arang/zo'rg'a).", "stem": "危うい", "optsTr": ["Bolaning ahvoli 'qilt ustida' (noto'g'ri — 怪しい).", "Mahallada 'shubhali' odam aylanib yuribdi (noto'g'ri — 怪しい).", "Kechasi qorong'i bo'lib yurish 'xavfli' (noto'g'ri — 危険/危ない).", "Cho'kib ketayozgandim, qilt ustida (arang, bir bahya qolganda) qutqarib qolishdi. (to'g'ri)"]}, {"id": "t4-v6-31", "options": ["彼のゴルフの腕前はまさに実物だ。", "この会社は名前だけで実物がない。", "写真では見ていたが、実物の美しさは想像以上だった。", "もし実物のダイヤなら、すごい値段のはずだ。"], "answer": 3, "tr": "実物 (じつぶつ) = asil nusxa, ko'z bilan ko'riladigan haqiqiy buyum.", "stem": "実物", "optsTr": ["Golf mahorati haqiqiy (noto'g'ri — 本物).", "Kompaniyaning mohiyati yo'q (noto'g'ri — 実質).", "Suratda ko'rgan edim, lekin haqiqiy buyumning o'zidagi go'zallik tasavvurimdan a'lo ekan. (to'g'ri)", "Asl brilliant (noto'g'ri — 本物)."]}, {"id": "t4-v6-32", "options": ["雨でもバザーは予測通りに行います。", "気象庁が予測した通り、今年の夏は異常に暑い。", "彼の競馬の予測は当たったためしがない。", "予測せぬ事態が起こり、会場は大混乱になった。"], "answer": 2, "tr": "予測 (よそく) = ilmiy yoki ma'lumotlarga asoslangan bashorat/taxmin.", "stem": "予測", "optsTr": ["Reja bo'yicha (noto'g'ri — 予定).", "Gidrometeorologiya markazi oldindan bashorat qilganidek, bu yil yoz g'ayritabiiy issiq bo'lmoqda. (to'g'ri)", "Ot poygasi taxmini (noto'g'ri — 予想).", "Kutilmagan vaziyat (noto'g'ri — 予期せぬ/予期しない)."]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t4-g1-33", "options": ["に反して", "に関して", "に応じて", "にしたがって"], "answer": 4, "tr": "Iqtisodiyot yomonlashib borgan sari, gazetadagi reklamalar ham kamayib boradi.", "stem": "景気が悪くなる（　）、新聞の広告が減ってくる。", "explanation_uz": "〜にしたがって = ...gan sari (bir narsa o'zgarishi bilan boshqasi ham o'zgarishi)"}, {"id": "t4-g1-34", "options": ["わりに", "かわりに", "ついでに", "ゆえに"], "answer": 1, "tr": "Bu restoran arzonligiga qaramasdan (arzonligiga yarasha) juda mazali bo'lgani sababli, doim mijozlarga to'la.", "stem": "このレストランは安い（　）おいしいので、いつも客でいっぱいだ。", "explanation_uz": "〜わりに (わりには) = ...ga qaramasdan, kutilganidan boshqacha"}, {"id": "t4-g1-35", "options": ["かぎり", "ばかり", "だけ", "きり"], "answer": 2, "tr": "Iye, Sato yana kelmadimi? Yaqindagina dam olgan edi-ku!", "stem": "え、佐藤さんはまた休みなの。こないだ休んだ（　）なのに。", "explanation_uz": "〜たばかり = yaqindagina ... bo'lgan"}, {"id": "t4-g1-36", "options": ["理由だ", "状態だ", "一方だ", "限界だ"], "answer": 3, "tr": "Oylik oshmayotgan bir paytda bola universitetga kirdi, turmush esa tobora qiyinlashib bormoqda.", "stem": "給料が上がらないのに子どもが大学に入り、生活が苦しくなる（　）。", "explanation_uz": "〜一方だ (いっぽうだ) = tobora faqat bir tomonga (yomon tomonga) qarab o'zgarmoqda"}, {"id": "t4-g1-37", "options": ["がち", "向き", "気味", "げ"], "answer": 3, "tr": "Bugun biroz shamollash alomati (shamollashdek holat) sezilgani uchun, vanna qilmay uxlayman.", "stem": "今日はかぜ（　）だから、おふろには入らないで寝ます。", "explanation_uz": "〜気味 (ぎみ) = biroz alomati bor, moyillik"}, {"id": "t4-g1-38", "options": ["とかいえば", "ともいえ", "とさえいえ", "とはいえ"], "answer": 4, "tr": "Garchi qonunni bilmagan bo'lsangiz ham, qoidani buzsangiz jinoyat hisoblanadi.", "stem": "たとえ法律を知らなかった（　）、決まりをやぶったら罪になる。", "explanation_uz": "〜とはいえ = garchi ... bo'lsa ham"}, {"id": "t4-g1-39", "options": ["いこうでは", "いかずには", "いっては", "いくわけで"], "answer": 1, "tr": "Kelinglar, bundan buyon barchamiz kuchimizni birlashtirib birgalikda harakat qilaylik!", "stem": "これから皆で力を合わせて、がんばって（　）ないか！", "explanation_uz": "〜（よう）ではないか = kelinglar, shunday qilaylik! (chaqiriq/targ'ib)"}, {"id": "t4-g1-40", "options": ["うかがってよろしいですか", "うかがっていただけますか", "申してよろしいですか", "申していただけますか"], "answer": 1, "tr": "A: «Allo, Sugiyama janoblari bormilar?»\nB: «Uzr, ismingizni so'rasam (bilsam) maylimi?»", "stem": "A「もしもし、杉山さんはいらっしゃいますか。」\nB「あの、お名前を（　）。」", "explanation_uz": "お名前をうかがってよろしいですか = ismingizni so'rasam maylimi (xushmuomala so'rov)"}, {"id": "t4-g1-41", "options": ["というわけではない", "といったところだ", "というわけだ", "といったようだ"], "answer": 1, "tr": "Harakat qilgan bilan albatta muvaffaqiyatga erishiladi degani emas, ammo qo'ldan kelgancha urinib ko'ramiz.", "stem": "がんばっても必ず成功する（　）が、やるだけはやろう。", "explanation_uz": "〜というわけではない = mutlaqo ... degani emas"}, {"id": "t4-g1-42", "options": ["出発するとすると", "出発したとすると", "出発するとしても", "出発したとしても"], "answer": 2, "tr": "Agar Kimura vaqtida uydan chiqqan deb hisoblasak, allaqachon yetib kelishi kerak edi, ammo hali ham yo'q.", "stem": "木村君が時間通りに家を（　）、もう着いているはずなのに、まだ来ていない。", "explanation_uz": "〜たとすると = agar ... deb faraz qilsak"}, {"id": "t4-g1-43", "options": ["やらざるを得ない", "やるわけにはいかない", "やるべきではない", "やらないかもしれない"], "answer": 1, "tr": "«O'zim qilaman» deb aytgan ekanman, o'zim qilmasdan boshqa ilojim yo'q.", "stem": "「私がやります」と言ったからには、私が（　）。", "explanation_uz": "〜からには〜ざるを得ない = aytgan ekansan, qilmaslikning iloji yo'q"}, {"id": "t4-g1-44", "options": ["してやったほうが", "させてやったほうが", "してあったほうが", "させてあったほうが"], "answer": 2, "tr": "Yosh xodimlarga mas'uliyatli ishni topshirib ko'rsak, o'zida ham ishtiyoq paydo bo'lmasmikin?", "stem": "若い社員に責任のある仕事を（　）、本人もやる気になるのではないか。", "explanation_uz": "〜させてやったほうが = qildirib ko'rgan ma'qulroq"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t4-g2-45", "options": ["子どもを", "必死に守るのに", "でさえ", "人間が"], "answer": 2, "tr": "To'g'ri tartib: 動物でさえ子どもを必死に守るのに、人間が子どもを捨てるなんて許せない。", "explanation_uz": "To'g'ri tartib: 動物[でさえ][子どもを][★必死に守るのに][人間が] (3 → 1 → 2 → 4)", "prefix": "動物", "suffix": "子どもを捨てるなんて許せない。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t4-v2-46", "options": ["かねる", "ことが", "理解", "し"], "answer": 1, "tr": "To'g'ri tartib: 今の若者の考えは理解しかねることが多すぎる。", "explanation_uz": "To'g'ri tartib: [理解][し][★かねる][ことが] (3 → 4 → 1 → 2)", "prefix": "今の若者の考えは", "suffix": "多すぎる。", "starPos": 3, "order": [3, 4, 1, 2]}, {"id": "t4-g2-47", "options": ["行く", "まったく", "行く", "町の様子"], "answer": 1, "tr": "To'g'ri tartib: 私が東京に行くたびに、まったく町の様子が変わっている気がする。", "explanation_uz": "To'g'ri tartib: 東京に[行く][たびに][★まったく][町の様子] (3 → 1 → 2 → 4)", "prefix": "私が東京に", "suffix": "が変わっている気がする。", "starPos": 2, "order": [3, 1, 2, 4]}, {"id": "t4-g2-48", "options": ["結果を", "お知らせ", "反した", "ご期待に"], "answer": 3, "tr": "To'g'ri tartib: 残念ながら、みなさんのご期待に反した結果をお知らせしなければなりません。", "explanation_uz": "To'g'ri tartib: みなさんの[ご期待に][★反した][結果を][お知らせ] (4 → 3 → 1 → 2)", "prefix": "残念ながら、みなさんの", "suffix": "しなければなりません。", "starPos": 2, "order": [4, 3, 1, 2]}, {"id": "t4-g2-49", "options": ["あり", "中止", "によっては", "ということ"], "answer": 4, "tr": "To'g'ri tartib: B「いや、天気によっては中止ということもあり得るよ。」", "explanation_uz": "To'g'ri tartib: 天気[によっては][中止][★ということ][も][あり] (3 → 2 → 4 → 1)", "prefix": "B「いや、天気", "suffix": "得るよ。」", "starPos": 3, "order": [3, 2, 4, 1]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "地震速報の仕組み", "passage": "地震のない国から日本に来た人が驚くことの1つに、テレビやラジオの緊急地震速報があります。番組の途中で突然チャイムが鳴り、「〇〇地方で地震です」とアナウンスが流れます。ふつう放送から大きな揺れが来るまで数秒くらいですが、その間に火を消したりテーブルにもぐったりできます。\nその後、すぐに震源はどこか、津波の心配があるかどうかも放送されます。\nこれは1995年の阪神・淡路大震災を契機に地震計が日本各地に置かれ始め、そのデータをもとに地震の情報を少しでも早く {{50}} 、研究が始まったものです。2007年から一般人向けに放送されるようになりました。世界でも初めてのシステムです。\nでも、なぜ揺れを感じるか {{51}} 地震や津波が来るとわかるのでしょうか。\n地震が起きると、P波と呼ばれる小さな揺れと、S波と呼ばれる大きな揺れが同時に発生します。P波は毎秒7km、S波は毎秒4kmで進みます。\n先に {{52-a}} が来たときに、どのくらい後に {{52-b}} が来るか予測して、緊急地震速報が発表されるのです。いくつかの地点のP波とS波の時間差を見ると、震源がどこかもわかります。\n海底にもたくさん地震計が置かれ、地震波を観測するとデータを衛星に送ります。地震波は海の波より100倍速く着くので、津波が来るかどうか {{53}} 。\n2004年のスマトラ島沖地震であったら、多くの人の命が助かったことでしょう。今や津波は「tsunami」と、世界でそのまま通じる言葉になりました。津波情報も国境を越えて発信する必要があります。\n緊急地震速報もまだまだ不完全ですが、地震の多い日本 {{54}} の発明と言えるでしょう。", "passage_tr": "Zilzila bo'lmaydigan mamlakatlardan Yaponiyaga kelgan kishilar hayron bo'ladigan jihatlardan biri — bu tele va radio orqali beriladigan favqulodda zilzila tezkor xabarlaridir. Ko'rsatuv davomida to'satdan signal chalinib, «falon mintaqada zilzila» degan e'lon yangraydi. Odatda efirdan katta silkinish yetib kelgunicha bir necha soniya bo'ladi, lekin shu vaqt ichida olovni o'chirish yoki stol tagiga yashirinishga ulgurish mumkin.\nShundan so'ng darhol epitsentr qayerdaligi va sunami xavfi bor-yo'qligi ham ma'lum qilinadi.\nBu 1995-yildagi Buyuk Xanshin zilzilasi sabab bo'lib, Yaponiya bo'ylab seysmometrlar o'rnatila boshlangach, ushbu ma'lumotlar orqali zilzila xabarini ozgina bo'lsa ham tezroq yetkazish uchun ilmiy izlanishlar boshlanishi bilan yaratilgan. 2007-yildan xalqqa e'lon qilina boshlandi. Bu dunyodagi ilk tizimdir.\nLekin nega silkinishni his etishdan oldinoq zilzila va sunami kelishini bilish mumkin?\nZilzila yuz berganda P-to'lqin deb ataluvchi kichik to'lqin va S-to'lqin deb ataluvchi kuchli to'lqin bir paytda yuzaga keladi. P-to'lqin soniyasiga 7 km, S-to'lqin esa soniyasiga 4 km tezlikda harakatlanadi.\nAvval P-to'lqin yetib kelganda, qancha vaqtdan keyin S-to'lqin yetib kelishi hisoblab chiqilib, tezkor xabar e'lon qilinadi.\nDengiz tubiga ham ko'plab seysmometrlar joylashtirilgan. Seysmik to'lqin dengiz to'lqinidan 100 baravar tez harakatlangani bois, sunami kelish-kelmasligini oldindan hisoblash mumkin bo'ladi.\nFavqulodda zilzila xabari hali mukammal bo'lmasa-da, zilzilalarga boy Yaponiyaga xos bo'lgan ajoyib ixtiro deyish mumkin.", "questions": [{"id": "t4-g3-50", "options": ["伝えまいと", "伝えようと", "伝えないと", "伝えるなら"], "answer": 2, "tr": "少しでも早く[伝えようと]、研究が始まった = ozgina bo'lsa ham tezroq yetkazaylik deb izlanishlar boshlangan.", "explanation_uz": "〜ようと = ...qilish niyati/maqsadi bilan", "blankNo": "50"}, {"id": "t4-g3-51", "options": ["感じないかのうちに", "感じないままに", "感じてからでないと", "感じたとたんに"], "answer": 1, "tr": "なぜ揺れを[感じないかのうちに]わかるのでしょうか = nega silkinishni hali his qilar-qilmas bilish mumkin?", "explanation_uz": "〜ないかのうちに = ...qilar-qilmas, birdaniga", "blankNo": "51"}, {"id": "t4-g3-52", "options": ["a P波 ／ b P波", "a S波 ／ b S波", "a S波 ／ b P波", "a P波 ／ b S波"], "answer": 4, "tr": "先に[a P波]が来たときに、どのくらい後に[b S波]が来るか予測して (Avval P-to'lqin, keyin S-to'lqin).", "explanation_uz": "Oldin kichik P-to'lqin (a), ortidan katta S-to'lqin (b)", "blankNo": "52"}, {"id": "t4-g3-53", "options": ["計算し得ません", "計算しかねません", "計算し得ます", "計算しかねます"], "answer": 3, "tr": "津波が来るかどうか[計算し得ます] = kelish-kelmasligini oldindan hisoblab chiqish imkoniyati bor.", "explanation_uz": "〜得る (うる/える) = amalga oshira oladi, imkoni bor", "blankNo": "53"}, {"id": "t4-g3-54", "options": ["といったら", "とあって", "だからこそ", "だからといって"], "answer": 3, "tr": "地震の多い日本[だからこそ]の発明と言えるでしょう = zilzilasi ko'p bo'lgan Yaponiyaga aynan xos bo'lgan ixtiro.", "explanation_uz": "〜だからこそ = aynan ... bo'lgani sababliki", "blankNo": "54"}]}]}]}, "5": {"id": 5, "title_jp": "第5回 模擬テスト", "title_uz": "5-test", "minutes": 45, "sections": [{"id": "vocab", "name_jp": "文字・語彙", "name_uz": "Kanji va lug'at", "problems": [{"id": "v1", "type": "kanji_reading", "instruction_jp": "＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning o'qilishi sifatida eng to'g'risini tanlang.", "questions": [{"id": "t5-v1-1", "options": ["へんごう", "へんか", "へんこう", "へんかん"], "answer": 3, "tr": "Ota-onamning moliyaviy ahvoli tufayli, kasb-hunar kollejiga borish yo'nalishini o'zgartirdim.", "stem": "親の経済事情で、専門学校へ進路を【変更】した。", "reading": "へんこう", "explanation_uz": "変更 → へんこう (o'zgartirish, boshqasiga almashtirish)"}, {"id": "t5-v1-2", "options": ["からんだ", "ふくらんだ", "にらんだ", "はらんだ"], "answer": 2, "tr": "Ushbu sport turida Olimpiadada ilk medalni qo'lga kiritishga bo'lgan umid yanada oshdi (kengaydi).", "stem": "この種目ではオリンピック初となるメダルへの期待が【膨らんだ】。", "reading": "ふくらんだ", "explanation_uz": "膨らむ → ふくらむ (kengaymoq, shishmoq, oshmoq)"}, {"id": "t5-v1-3", "options": ["きろん", "しょろん", "がいろん", "じろん"], "answer": 3, "tr": "Talabalar orasida mashhurlik qozonayotgani «Iqtisodiyotga kirish / umumiy asoslari» kursidir.", "stem": "学生に人気があるのは「経済学【概論】」の講座だ。", "reading": "がいろん", "explanation_uz": "概論 → がいろん (kirish kursi, umumiy asoslar)"}, {"id": "t5-v1-4", "options": ["とうじょう", "ちょうじょう", "こうじょう", "ていじょう"], "answer": 2, "tr": "Mening toqqa chiqishdan maqsadim cho'qqiga chiqish emas, balki tabiatdan xotirjam zavqlanishdir.", "stem": "私の登山の目的は【頂上】に立つことではなく、大自然をゆっくり楽しむことにある。", "reading": "ちょうじょう", "explanation_uz": "頂上 → ちょうじょう (cho'qqi, eng baland nuqta)"}, {"id": "t5-v1-5", "options": ["すいじゅん", "すいじゅん", "すいしゅん", "ずいしゅん"], "answer": 2, "tr": "Tokio hukumati tibbiyot darajasini oshirishga qaratilgan yangi tizimni e'lon qildi.", "stem": "東京都は医療【水準】の向上を目指す新制度を発表した。", "reading": "すいじゅん", "explanation_uz": "水準 → すいじゅん (daraja, saviya)"}]}, {"id": "v2", "type": "orthography", "instruction_jp": "＿＿の言葉を漢字で書くとき、最もよいものを1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zning to'g'ri kanji yozuvini tanlang.", "questions": [{"id": "t5-v2-6", "options": ["苦痛", "苦適", "具痛", "悲痛"], "answer": 1, "tr": "Zaif mavqedagi insonga ruhiy va jismoniy azob (og'riq) yetkazish vakolatni suiiste'mol qilish (power harassment) deyiladi.", "stem": "弱い立場の人に精神的、身体的【くつう】を与えることをパワーハラスメントという。", "reading": "くつう", "explanation_uz": "苦痛 → くつう (azob, og'riq)"}, {"id": "t5-v2-7", "options": ["冷えて", "寒えて", "凍えて", "涼えて"], "answer": 3, "tr": "Bugun ertalab qo'llar uvishib (muzlab), biror narsani ushlab bo'lmaydigan darajada sovuq edi.", "stem": "今朝は手が【こごえて】、物がうまくつかめないほど寒かった。", "reading": "こごえて", "explanation_uz": "凍える → こごえる (muzlamoq, uvishmoq)"}, {"id": "t5-v2-8", "options": ["挟って", "握って", "担って", "捕って"], "answer": 2, "tr": "Raqib jamoaning zaif tomonini qo'lga kiritib olganimiz (ushlab olganimiz) sababli, o'yinni o'zimizga qulay olib bordik.", "stem": "相手チームの弱点を【にぎって】いたので、試合を有利に進めることができた。", "reading": "にぎって", "explanation_uz": "握る → にぎる (siqimlab ushlamoq, qo'lda tutmoq)"}, {"id": "t5-v2-9", "options": ["理外", "理害", "利外", "利害"], "answer": 4, "tr": "Hamkor kompaniya bilan o'zaro manfaatlar mos kelib, shartnoma masalasi hal bo'ldi.", "stem": "取引先と【りがい】が一致して、契約の話がまとまった。", "reading": "りがい", "explanation_uz": "利害 → りがい (foyda va ziyon, manfaat)"}, {"id": "t5-v2-10", "options": ["克服", "告服", "降服", "攻服"], "answer": 1, "tr": "Og'ir mashg'ulotlarni ketma-ket bajarib, nihoyat o'z kamchiligimni yengib o'tishga (bartaraf etishga) muvaffaq bo'ldim.", "stem": "厳しいトレーニングを積み重ねて、やっと自分の欠点を【こくふく】することができた。", "reading": "こくふく", "explanation_uz": "克服 → こくふく (yengib o'tish, mag'lub etish)"}]}, {"id": "v3", "type": "context", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Qavs ichiga eng mos keladigan so'z/affiksni tanlang.", "questions": [{"id": "t5-v3-11", "options": ["力", "重", "諸", "全"], "answer": 1, "tr": "Bu yumush jismoniy og'ir ish (kuch talab qiladigan ish) bo'lmagani uchun, keksalar uchun mos keladi.", "stem": "この作業は（　）仕事ではないので、お年寄りに向いている。", "explanation_uz": "力仕事 (ちからしごと) = og'ir jismoniy mehnat"}, {"id": "t5-v3-12", "options": ["中", "下", "外", "内"], "answer": 4, "tr": "O'tirish qandaydir qilib har bir kishiga 3000 iyen byudjet doirasida (ichida) yakunlandi.", "stem": "飲み会はなんとか1人3000円の予算（　）におさまった。", "explanation_uz": "予算内 (よさんない) = byudjet doirasida/ichida"}, {"id": "t5-v3-13", "options": ["家", "者", "人", "民"], "answer": 2, "tr": "U shahardagi nufuzli (ta'sir doirasi katta) shaxsdir.", "stem": "彼は町の有力（　）だ。", "explanation_uz": "有力者 (ゆうりょくしゃ) = nufuzli, obro'li shaxs"}, {"id": "t5-v3-14", "options": ["単", "各", "唯", "一"], "answer": 4, "tr": "Bu faqat bir shaxs (oddiy inson) sifatidagi shaxsiy fikrimdir.", "stem": "これは（　）個人としての意見です。", "explanation_uz": "一見 / 一個人 (いっこじん) = alohida bir shaxs, oddiy inson"}, {"id": "t5-v3-15", "options": ["感", "考", "観", "想"], "answer": 3, "tr": "Betob bo'lib chiqqanimdan beri hayotga bo'lgan qarashim (dunyoqarashim) butunlay o'zgardi.", "stem": "病気をして以来、人生（　）が変わった。", "explanation_uz": "人生観 (じんせいかん) = hayotga bo'lgan qarash, dunyoqarash"}]}, {"id": "v4", "type": "paraphrase", "instruction_jp": "（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga ma'no jihatidan eng mos keladigan so'zni tanlang.", "questions": [{"id": "t5-v4-16", "options": ["大事", "優先", "貴重", "重要"], "answer": 4, "tr": "Sharq tabobati butun vujudni ko'tarib turuvchi oyoqlarni alohida muhim (ahamiyatli) deb biladi.", "stem": "東洋医学は、全身を支える足を特に（　）視する。", "explanation_uz": "重要視する (じゅうようしする) = juda muhim deb hisoblamoq"}, {"id": "t5-v4-17", "options": ["増大", "急増", "増減", "激増"], "answer": 1, "tr": "Konditsioner chiqarib tashlayotgan issiqlik tashqaridagi havoni yanada qizdirib (kuchaytirib) yubormoqda.", "stem": "エアコンが吐き出す熱が、外の暑さをさらに（　）させている。", "explanation_uz": "増大 (ぞうだい) = kuchayish, ortish, ko'payish"}, {"id": "t5-v4-18", "options": ["あちこち", "まあまあ", "いちいち", "それぞれ"], "answer": 3, "tr": "Endi yosh bola emassan, har bitta mayda-chuyda narsani aytilmasa ham o'zing hal qilgin.", "stem": "もう子どもではないんだから、（　）言われなくても自分で決めなさいよ。", "explanation_uz": "いちいち = birma-bir, har bir mayda narsagacha"}, {"id": "t5-v4-19", "options": ["パート", "パーソナル", "パターン", "パッケージ"], "answer": 4, "tr": "Ushbu tovar sotilmasligining bir sababi uning qadoqlanish (package) dizayni o'ta oddiyligidir deb o'ylayman.", "stem": "この商品が売れない原因の1つは商品の（　）のデザインが平凡すぎるからだと思う。", "explanation_uz": "パッケージ (package) = qadoq, qadoqlash"}, {"id": "t5-v4-20", "options": ["面倒", "世話", "加減", "手数"], "answer": 1, "tr": "Ishdagi muammo bo'lsa, xodimlarga yaxshi qaraydigan (g'amxo'r) rahbarga maslahat solgan ma'qul.", "stem": "仕事の悩みなら（　）見のよい職場の上司に相談するのがいちばんだと思う。", "explanation_uz": "面倒見のよい (めんどうみのよい) = g'amxo'r, yaxshi qaraydigan"}, {"id": "t5-v4-21", "options": ["かしこい", "ふさわしい", "おめでたい", "したい"], "answer": 3, "tr": "Doktorlik unvonini oldi, to'yi ham belgilandi — uning uchun faqat quvonchli (muborak) ishlar davom etmoqda.", "stem": "博士号は取るし、結婚も決まったし、彼にとって（　）ことが続いている。", "explanation_uz": "おめでたい = quvonchli, tabriklashga arziydigan"}, {"id": "t5-v4-22", "options": ["包む", "含む", "帯びる", "握る"], "answer": 2, "tr": "Biroz toliqqandek bo'lsangiz, tarkibida C vitamini ko'p bo'lgan (o'z ichiga olgan) ozuqalarni iste'mol qilgan ma'qul.", "stem": "疲れ気味かなと思ったら、ビタミンCを多く（　）食品をとるといい。", "explanation_uz": "含む (ふくむ) = o'z ichiga olmoq, tarkibida bo'lmoq"}]}, {"id": "v5", "type": "usage", "instruction_jp": "＿＿の言葉に意味が最も近いものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Tagiga chizilgan so'zga ma'nosi eng yaqin sinonimni tanlang.", "questions": [{"id": "t5-v5-23", "options": ["延期になった", "中止になった", "見直された", "変更になった"], "answer": 2, "tr": "Sayr (hiking) yomg'ir sababli bekor qilindi (amalga oshmadi).", "stem": "ハイキングは雨で【流れた】。", "reading": "ながれた", "explanation_uz": "流れる → 中止になった (bekor bo'lmoq, qolib ketmoq)"}, {"id": "t5-v5-24", "options": ["すっかり", "ぼんやり", "くっきり", "いきなり"], "answer": 4, "tr": "Osmon to'satdan qorayib, yirik tomchili yomg'ir yog'a boshladi.", "stem": "空が【にわかに】暗くなり、大粒の雨が降り出した。", "reading": "にわかに", "explanation_uz": "にわかに = いきなり (to'satdan, birdaniga)"}, {"id": "t5-v5-25", "options": ["冷静な", "鋭い", "確かな", "温かい"], "answer": 1, "tr": "U doim atrof-olamga vazmin (hissiyotga berilmasdan, sovuqqon) nigoh bilan qaraydi.", "stem": "彼女はいつも【覚めた】目で世間を見ている。", "reading": "さめた", "explanation_uz": "覚めた目 = 冷静な (vazmin, bosiq, mulohazali)"}, {"id": "t5-v5-26", "options": ["むりやり", "こっそり", "しきりに", "わざわざ"], "answer": 1, "tr": "Do'stim meni majburlab (zo'rlab) bazmga sudrab olib bordi.", "stem": "友人に【強引に】パーティーに連れて行かれた。", "reading": "ごういんに", "explanation_uz": "強引に = むりやり (majburlab, zo'ravonlik bilan)"}, {"id": "t5-v5-27", "options": ["理解して", "評価して", "応援して", "仕上げて"], "answer": 3, "tr": "Katta hamkasbim mening ishimni qo'llab-quvvatlab (yordam berib) turadi.", "stem": "先輩は私の仕事を【サポート】してくれる。", "explanation_uz": "サポートする = 応援して (yordam bermoq, suyamoq)"}]}, {"id": "v6", "type": "usage_special", "instruction_jp": "次の言葉の使い方として最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Quyidagi so'zning eng to'g'ri ishlatilgan gapini tanlang.", "questions": [{"id": "t5-v6-28", "options": ["通勤時間を圧縮するため引っ越しをする。", "景気が悪いので、社員数を圧縮しなければならない。", "袋にふとんを入れて空気を抜くと、薄く圧縮できる。", "スカート丈を3センチ圧縮したら、イメージが変わった。"], "answer": 3, "tr": "圧縮 (あっしゅく) = siqish, hajmini kichraytirish (havosini chiqarib qisish).", "stem": "圧縮", "optsTr": ["Yo'l vaqtini qisqartirish (noto'g'ri — 短縮).", "Xodimlar sonini qisqartirish (noto'g'ri — 削減).", "Xaltaga ko'rpani solib havosini so'rib olinsa, yupqa qilib siqib (presslab) qo'yish mumkin. (to'g'ri)", "Yubkani kaltalatish (noto'g'ri — 詰める)."]}, {"id": "t5-v6-29", "options": ["このお菓子の名前はぼろがいい。", "彼女、上品ぶっているけれど、そのうちぼろを出すよ。", "去年買った服のデザインがぼろになって着られない。", "彼は他人のぼろばかり探すいやな男だ。"], "answer": 2, "tr": "ぼろ = yashiringan kamchilik, nuqson (ぼろを出す = sirini/kamchiligini fosh qilib qo'ymoq).", "stem": "ぼろ", "optsTr": ["Shirinlikning nomi yaxshi (noto'g'ri — ごろ).", "U o'zini olijanob ko'rsatmoqda, ammo tez orada asl qiyofasini (kamchiligini) fosh qilib qo'yadi. (to'g'ri)", "Kiyim dizayni eskirib (noto'g'ri — 流行遅れ).", "Odamlarning kamchiligini qidiradi (noto'g'ri — あら)."]}, {"id": "t5-v6-30", "options": ["これはたいへん上等なお品でございます。", "あの子は病気の母親の世話をして上等だ。", "上等な考えを持っている若者もたくさんいる。", "彼女は1人で5人の子どもを育てた上等な女性だ。"], "answer": 1, "tr": "上等 (じょうとう) = yuqori sifatli, a'lo darajali (buyum/mahsulot haqida).", "stem": "上等", "optsTr": ["Bu juda yuqori sifatli (a'lo darajadagi) buyumdir. (to'g'ri)", "Onasiga qarab 'a'lo' (noto'g'ri — えらい/感心).", "Ajoyib fikrga ega (noto'g'ri — 立派な).", "Ulug' ayol (noto'g'ri — 立派な)."]}, {"id": "t5-v6-31", "options": ["今日の練習の規律はいつもより忙しい。", "彼はまるで軍隊のように規律正しい生活をしている。", "社長の大胆な規律で会社は危機を脱した。", "受験資格を経験者だけに規律する。"], "answer": 2, "tr": "規律 (きりつ) = intizom, tartib-qoida (規律正しい = intizomli).", "stem": "規律", "optsTr": ["Mashg'ulot jadvali (noto'g'ri — スケジュール).", "U xuddi armiyadagidek qat'iy intizomli hayot kechiradi. (to'g'ri)", "Prezidentning qat'iy qarori (noto'g'ri — 決断).", "Tajribalilarga cheklash (noto'g'ri — 限定)."]}, {"id": "t5-v6-32", "options": ["こんな結果になるなんて空想もつきませんでした。", "子どものころからスターになる空想を見続けている。", "将来の生活の空想を立ててください。", "彼女は「もし大金持ちと結婚したら」とか、空想ばかりしている。"], "answer": 4, "tr": "空想 (くうそう) = xayol surish, fantaziya (asossiz xayollar).", "stem": "空想", "optsTr": ["Bunday bo'lishini o'ylamovdim (noto'g'ri — 予想).", "Yulduz bo'lish orzusini ko'rmoqda (noto'g'ri — 夢).", "Reja tuzing (noto'g'ri — 計画).", "U doim «agar boy odamga tegsam» kabi asossiz xayollarni suraveradi. (to'g'ri)"]}]}]}, {"id": "grammar", "name_jp": "文法", "name_uz": "Grammatika", "problems": [{"id": "g1", "type": "grammar_form", "instruction_jp": "次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ( ) ga qo'yish uchun eng mos grammatik shaklni tanlang.", "questions": [{"id": "t5-g1-33", "options": ["ながらも", "かわりに", "とはいえ", "上に"], "answer": 4, "tr": "Mening xonam keng bo'lishi ustiga-ustak, yangi va juda shinamdir.", "stem": "私の部屋は広い（　）、新しくて気持ちがよい。", "explanation_uz": "〜上に (うえに) = ...ning ustiga-ustak, bundan tashqari"}, {"id": "t5-g1-34", "options": ["に続いて", "にかけて", "に渡って", "に及んで"], "answer": 2, "tr": "Ertadan dam olish kunlarigacha butun mamlakat bo'ylab yaxshi ob-havo davom etsa kerak.", "stem": "明日から週末（　）、全国的によい天気が続くでしょう。", "explanation_uz": "〜から〜にかけて = ...dan ...gacha bo'lgan davrda"}, {"id": "t5-g1-35", "options": ["いうこと", "いう人", "いうもの", "いうわけ"], "answer": 3, "tr": "Yomonligini bilaturib ham ba'zida gunoh qiladi. Inson tabiati degani o'zi shunaqa-da.", "stem": "悪いとわかっていても、時には罪をおかす。それが人間と（　）だ。", "explanation_uz": "〜というものだ = ...tabiati shundaydir (inson tabiati)"}, {"id": "t5-g1-36", "options": ["ならない", "なれない", "なるまい", "なりきれない"], "answer": 1, "tr": "Atigi bir raqam farqi bilan lotereyada yutqazib qo'yish — shunchalik alam qiladiki, chidab bo'lmaydi.", "stem": "たった1番違いで宝くじに外れるなんて、くやしくて（　）。", "explanation_uz": "〜てならない = juda ham, his-tuyg'uni jilovlab bo'lmaydi"}, {"id": "t5-g1-37", "options": ["なんとか", "なんでも", "なににとぞ", "なにしろ"], "answer": 4, "tr": "A: «Rangingiz o'chiq-ku.»\nB: «Nima bo'lganda ham juda band bo'lib, dam olishga fursat yo'q-da.»", "stem": "A「顔色が悪いですね。」\nB「（　）忙しくて、休むひまがないんです。」", "explanation_uz": "なにしろ = nima bo'lganda ham, qanday bo'lmasin"}, {"id": "t5-g1-38", "options": ["病気みたい", "病気がち", "病気っぽい", "病気ぎみ"], "answer": 2, "tr": "Bolaligimda tez-tez kasal bo'lib turar edim, ammo butunlay baquvvat bo'lib ketdim.", "stem": "子どものときは（　）でしたが、すっかり丈夫になりました。", "explanation_uz": "〜がち = tez-tez ... bo'ladigan (moyil bo'lgan)"}, {"id": "t5-g1-39", "options": ["食べるうちに", "食べたうちに", "食べもしないで", "食べるそばから"], "answer": 1, "tr": "Boshida yoqtirmagan yapon taomlarini ham asta-sekin yeyaverish asnosida yoqtirib qoldim.", "stem": "最初は嫌いだった日本食も、少しずつ（　）好きになってきた。", "explanation_uz": "〜うちに = ...qilib yuraverish davomida (o'zgarish sodir bo'lishi)"}, {"id": "t5-g1-40", "options": ["おっしゃってください", "申されてください", "言われていただけますか", "申していただけますか"], "answer": 1, "tr": "Xitoy tilini yaxshi bilaman. Tarjimon kerak bo'lsa xohlagan paytda aytavering.", "stem": "中国語は得意です。通訳が必要ならいつでも（　）。", "explanation_uz": "おっしゃってください = ayting, buyuring (xushmuomala so'rov: 言う ning sonkeigo shakli)"}, {"id": "t5-g1-41", "options": ["長生きをしたいものだ", "長生きはするものだ", "長生きをしたくないものだ", "長生きはしないものだ"], "answer": 3, "tr": "U doim «to'shakka mixlanib qolguncha uzoq yashashni aslo xohlamasdim» deydi-yu, lekin ozgina betob bo'lsa shov-shuv ko'taradi.", "stem": "彼はよく「寝たきりになってまで（　）」と言うが、病気になると大騒ぎする。", "explanation_uz": "〜たくないものだ = aslo ... bo'lishni xohlamasdim"}, {"id": "t5-g1-42", "options": ["とてもうまくなった", "あまりうまくならなかった", "きっ とうまくなるだろう", "うまくなるべきだ"], "answer": 2, "tr": "Bolaligimdan beri pianino o'rganib kelgan bo'lsam-da, unchalik yaxshi o'rganib keta olmadim.", "stem": "子どものときからずっとピアノを習ってはきたものの、（　）。", "explanation_uz": "〜ものの = ...gan bo'lsa-da (kutilgan natija bo'lmadi)"}, {"id": "t5-g1-43", "options": ["まずいわけではない", "まずくないわけでもない", "まずいわけがない", "まずくないわけにもいかない"], "answer": 3, "tr": "Eng sara masalliqlardan eng yetuk oshpaz tayyorlagan ekan, bemaza bo'lishi aslo mumkin emas!", "stem": "最高の材料で最高のシェフが作ったのだから、（　）。", "explanation_uz": "〜わけがない = aslo ... bo'lishi mumkin emas"}, {"id": "t5-g1-44", "options": ["することにはならない", "することにはならない", "したことにはなる", "したことになる"], "answer": 1, "tr": "Talabalar festivali haqida shunchaki fikr aytib, o'zing hech narsa qilmasang, qatnashgan hisoblanmaysan.", "stem": "学園祭について、ただ意見を言うだけで何もしなければ、参加（　）。", "explanation_uz": "〜ことにはならない = ...qilgan deb hisoblab bo'lmaydi"}]}, {"id": "g2", "type": "sentence_order", "instruction_jp": "次の文の ★ に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Gapdagi ★ o'rniga tushadigan eng to'g'ri bo'lakni tanlang.", "questions": [{"id": "t5-g2-45", "options": ["発音", "だけ", "アメリカ育ち", "あって"], "answer": 4, "tr": "To'g'ri tartib: 彼女の英語はアメリカ育ちだけあって発音はきれいだが、文法は正しくない。", "explanation_uz": "To'g'ri tartib: [アメリカ育ち][だけ][★あって][発音] (3 → 2 → 4 → 1)", "prefix": "彼女の英語は", "suffix": "はきれいだが、文法は正しくない。", "starPos": 3, "order": [3, 2, 4, 1]}, {"id": "t5-g2-46", "options": ["とき", "あやまらざる", "お客様に", "を得ない"], "answer": 2, "tr": "To'g'ri tartib: 私のミスではないのにお客様にあやまらざるを得ないときも、たまにはあります。", "explanation_uz": "To'g'ri tartib: [お客様に][★あやまらざる][を得ない][とき] (3 → 2 → 4 → 1)", "prefix": "私のミスではないのに", "suffix": "も、たまにはあります。", "starPos": 2, "order": [3, 2, 4, 1]}, {"id": "t5-g2-47", "options": ["しても", "建てる", "と", "ずっと"], "answer": 3, "tr": "To'g'ri tartib: もし私が家を建てるとしたら、ずっと町の中心から遠いところだ。", "explanation_uz": "To'g'ri tartib: [建てる][★と][しても][ずっと] (2 → 3 → 1 → 4)", "prefix": "もし私が家を", "suffix": "町の中心から遠いところだ。", "starPos": 2, "order": [2, 3, 1, 4]}, {"id": "t5-g2-48", "options": ["限り", "雨の日", "来ない", "台風でも"], "answer": 1, "tr": "To'g'ri tartib: 優勝したマラソン選手は台風でも来ない限り、雨の日も練習を休むことはないそうだ。", "explanation_uz": "To'g'ri tartib: [台風でも][来ない][★限り][雨の日] (4 → 3 → 1 → 2)", "prefix": "優勝したマラソン選手は", "suffix": "も練習を休むことはないそうだ。", "starPos": 3, "order": [4, 3, 1, 2]}, {"id": "t5-g2-49", "options": ["収穫量は", "次第", "秋の", "夏の天気"], "answer": 4, "tr": "To'g'ri tartib: 米や果物の秋の収穫量は夏の天気次第です。", "explanation_uz": "To'g'ri tartib: [秋の][収穫量は][★夏の天気][次第] (3 → 1 → 4 → 2)", "prefix": "米や果物の", "suffix": "です。", "starPos": 3, "order": [3, 1, 4, 2]}]}, {"id": "g3", "type": "text_grammar", "instruction_jp": "次の文章を読んで、50から54の中に入る最もよいものを、1・2・3・4から一つ選びなさい。", "instruction_uz": "Matnni o'qib, 50-54 bo'sh joylariga eng to'g'ri variantni tanlang.", "passage_title": "緑のカーテン", "passage": "最近の日本の夏の暑さには異常な {{50}} 。\n以前は体に悪いと言われたエアコンも、今では使わないと命が {{51}} 。しかしエアコンをつけると熱い空気が外に吹き出て外の空気が温まり、日が落ちても地面の温度が下がらず、夜も暑いままです。エアコンを使うことが、夏をますます {{52}} とも言えます。\n最近街を歩いていて、窓の外やベランダ一面にひもがつるされたり棒が立てられていて、下に植えた植物の葉が茂っているのを見かけませんか。あれを「緑のカーテン」と言います。\n人間が暑いと汗をかくように、植物も暑くなると根から水を吸い、葉の表面が汗をかいたようにぬれます。 {{53-a}} 葉の間を空気が通ると、 {{53-b}} 葉の間を通るよりたくさんの熱を奪います。そのために空気の温度が下がります。\nエアコンのない小学校で「緑のカーテン」を作ったところ、今まで暑くて勉強できなかった窓際の生徒たちも、落ち着いて勉強できるようになりました。\n電気代もかからないし、外の地面をあたためることもありません。緑色は勉強で疲れた目を休めるし、実のなる植物なら実を給食に使うこともあるそうです。電気代の節約 {{54}} 、見た目にも美しく食べることもできると、よいことばかりです。\n市役所が住民に「ぜひ緑のカーテンを作ってください」と呼びかけているところもあります。地球温暖化を食い止めるためにも、広がってほしいものです。", "passage_tr": "So'nggi paytlarda Yaponiyada yozning issiqligi g'ayritabiiy darajada deb aytish mumkin.\nIlgari salomatlikka yomon deb qaralgan konditsioner ham hozir ishlatilmasa hayot xavf ostida qoladigan darajada. Ammo konditsionerni yoqqanda issiq havo tashqariga haydalib, ko'chadagi havo isiydi, quyosh botsa ham yer soviymay, kechalari ham issiqligicha qoladi. Konditsioner ishlatish yozni yanada issiqroq qilmoqda deyish ham mumkin.\nYaqinda ko'chada yurganda derazalar tashqarisida yoki balkonda iplar tortilib, o'simlik barglari qoplab turganiga ko'zingiz tushmadimi? Buni «Yashil parda» (Midori no kaaten) deb atashadi.\nInson issiqda terlaganidek, o'simlik ham issiq bo'lganda ildizidan suv tortib, barglar sathi xuddi terlagandek namlanadi. Namlangan barglar orasidan havo o'tsa, quruq barglar orasidan o'tgandan ko'ra ancha ko'p issiqlikni o'ziga yutadi. Shu sababli havoning harorati pasayadi.\nKonditsioneri bo'lmagan maktabda «yashil parda» o'rnatilgach, issiqdan o'qiy olmagan deraza yonidagi o'quvchilar ham xotirjam o'qiy boshladilar.\nElektr energiyasini tejash-ku mayli, ko'rinishi ham chiroyli va mevasini yeyish ham mumkin — faqatgina yaxshilik keltiradi.", "questions": [{"id": "t5-g3-50", "options": ["ことがあります", "ものがあります", "わけです", "ところです"], "answer": 2, "tr": "夏の暑さには異常な[ものがあります] = yozning issiqligida g'ayritabiiylik bor.", "explanation_uz": "〜ものがある = ...deb hisoblaydigan jihati bor", "blankNo": "50"}, {"id": "t5-g3-51", "options": ["危ないばかりです", "危ないはずです", "危ないほどです", "危ないところです"], "answer": 3, "tr": "使わないと命が[危ないほどです] = ishlatilmasa hayot xavf ostida qoladigan darajada.", "explanation_uz": "〜ほどです = ...darajada", "blankNo": "51"}, {"id": "t5-g3-52", "options": ["過ごしやすくする", "暑くしている", "涼しくする", "快適にする"], "answer": 2, "tr": "夏をますます[暑くしている]とも言えます = yozni yanada issiqroq qilmoqda deyish ham mumkin.", "explanation_uz": "Issiqlik tashqariga chiqishi sababli: 暑くしている", "blankNo": "52"}, {"id": "t5-g3-53", "options": ["a ぬれた ／ b かわいた", "a かわいた ／ b ぬれた", "a ぬれた ／ b ぬれた", "a かわいた ／ b かわいた"], "answer": 1, "tr": "a ぬれた (nam) barglar oralig'idan o'tsa, b かわいた (quruq) barglardan o'tgandan ko'proq issiqlikni yutadi.", "explanation_uz": "Tartib: a ぬれた / b かわいた", "blankNo": "53"}, {"id": "t5-g3-54", "options": ["はともかく", "どころか", "ばかりで", "のみならず"], "answer": 4, "tr": "電気代の節約[のみならず]、見た目にも美しく = elektr tejashdan tashqari, ko'rinishi ham go'zal.", "explanation_uz": "〜のみならず = faqatgina ... bo'lib qolmasdan, balki", "blankNo": "54"}]}]}]}};
